INSERT INTO brands (id, name, description, status) VALUES
    (1, 'Cocoon Vietnam', 'Thương hiệu mỹ phẩm thuần chay 100% từ thực vật Việt Nam như bí đao, cà phê Đắk Lắk, bưởi, hoa hồng.', 'ACTIVE'),
    (2, 'La Roche-Posay', 'Thương hiệu dược mỹ phẩm hàng đầu từ Pháp được hơn 90.000 chuyên gia da liễu toàn cầu khuyên dùng.', 'ACTIVE'),
    (3, 'The Ordinary', 'Thương hiệu chăm sóc da nổi tiếng Canada tiên phong với nồng độ hoạt chất tinh khiết minh bạch giá hợp lý.', 'ACTIVE'),
    (4, 'Paula''s Choice', 'Dược mỹ phẩm cao cấp của Mỹ nổi tiếng với các sản phẩm tẩy da chết BHA/AHA và Retinol khoa học.', 'ACTIVE'),
    (5, 'Innisfree', 'Thương hiệu mỹ phẩm tự nhiên hàng đầu Hàn Quốc với chiết xuất từ thiên nhiên tươi đẹp đảo Jeju.', 'ACTIVE'),
    (6, 'CeraVe', 'Dược mỹ phẩm phát triển bởi chuyên gia da liễu Mỹ chứa phức hợp 3 Ceramide thiết yếu phục hồi da.', 'ACTIVE'),
    (7, 'Anessa', 'Thương hiệu chống nắng chuyên nghiệp số 1 Nhật Bản thuộc tập đoàn Shiseido suốt 21 năm liên tiếp.', 'ACTIVE'),
    (8, 'L''Oréal Paris', 'Tập đoàn mỹ phẩm và làm đẹp lớn nhất thế giới từ Pháp với công nghệ làm đẹp tiên tiến bậc nhất.', 'ACTIVE'),
    (9, 'Laneige', 'Thương hiệu mỹ phẩm cao cấp Hàn Quốc dẫn đầu xu hướng ẩm mượt căng mọng Water Bank và cushion mỏng mịn.', 'ACTIVE'),
    (10, 'MAC Cosmetics', 'Thương hiệu trang điểm chuyên nghiệp đẳng cấp quốc tế của Mỹ tôn vinh vẻ đẹp cá tính thời thượng.', 'ACTIVE'),
    (11, 'Maybelline New York', 'Thương hiệu trang điểm số 1 thế giới với những dòng mascara, cushion và son lì dẫn đầu xu hướng New York.', 'ACTIVE'),
    (12, 'Vichy', 'Dược mỹ phẩm Pháp sử dụng 100% nước khoáng núi lửa ngàn năm tuổi giàu 15 khoáng chất quý phục hồi da.', 'ACTIVE'),
    (13, 'Estée Lauder', 'Tập đoàn mỹ phẩm cao cấp sang trọng của Mỹ với tinh chất chống lão hóa ban đêm huyền thoại ANR.', 'ACTIVE'),
    (14, 'Bioderma', 'Thương hiệu dược mỹ phẩm Pháp sáng chế công nghệ nước tẩy trang Micellar Water Sensibio H2O số 1 toàn cầu.', 'ACTIVE'),
    (15, 'Klairs', 'Thương hiệu mỹ phẩm thuần chay lành tính Hàn Quốc chăm sóc an toàn cho làn da nhạy cảm nhất.', 'ACTIVE'),
    (16, 'Simple', 'Thương hiệu chăm sóc da số 1 Vương quốc Anh dịu nhẹ thuần khiết không cồn không hương liệu nhân tạo.', 'ACTIVE'),
    (17, 'Eucerin', 'Dược mỹ phẩm chuyên khoa da liễu hơn 100 năm tuổi của Đức được tin dùng tại các bệnh viện da liễu.', 'ACTIVE'),
    (18, 'Kiehl''s', 'Thương hiệu dược mỹ phẩm cao cấp New York từ năm 1851 kết hợp tinh hoa thảo mộc và khoa học hiện đại.', 'ACTIVE'),
    (19, 'Sulwhasoo', 'Mỹ phẩm thảo dược Đông y Hoàng gia cao cấp Hàn Quốc với chiết xuất Nhân sâm quý báu chống lão hóa.', 'ACTIVE'),
    (20, 'Dior', 'Nhà mốt làm đẹp thời trang xa xỉ bậc nhất nước Pháp với các tuyệt tác son môi, kem nền và nước hoa sang trọng.', 'ACTIVE'),
    (21, 'Chanel', 'Biểu tượng thời trang và nước hoa xa xỉ trường tồn nước Pháp với những hương thơm quý phái say đắm.', 'ACTIVE'),
    (22, 'YSL', 'Thương hiệu mỹ phẩm xa xỉ Yves Saint Laurent Pháp nổi bật với phong cách quyến rũ, cá tính và sắc sảo.', 'ACTIVE'),
    (23, 'Rom&nd', 'Thương hiệu trang điểm Hàn Quốc cực thịnh với các bảng màu son tint bóng căng mọng và phấn mắt ngọt ngào.', 'ACTIVE'),
    (24, '3CE Stylenanda', 'Thương hiệu thời trang trang điểm phong cách Hàn Quốc tạo nên trào lưu son kem lì và má hồng tươi tắn.', 'ACTIVE'),
    (25, 'Sunplay Skin Aqua', 'Thương hiệu chống nắng dưỡng da dạng sữa lỏng nhẹ giá mềm bán chạy số 1 tại các nhà thuốc Việt Nam.', 'ACTIVE'),
    (26, 'DHC', 'Thương hiệu thực phẩm chức năng và dầu tẩy trang Oliu nguyên chất hàng đầu Nhật Bản an toàn cho làn da.', 'ACTIVE'),
    (27, 'Moroccanoil', 'Thương hiệu chăm sóc tóc chuyên nghiệp cao cấp Israel tiên phong với tinh dầu Argan dưỡng tóc bóng mượt.', 'ACTIVE'),
    (28, 'Tsubaki', 'Thương hiệu chăm sóc tóc chuẩn Salon Nhật Bản chiết xuất từ hoa trà đỏ phục hồi tóc hư tổn bóng bẩy.', 'ACTIVE'),
    (29, 'Bath & Body Works', 'Thương hiệu chăm sóc cơ thể và xịt thơm Body Mist số 1 nước Mỹ với hàng trăm mùi hương quyến rũ.', 'ACTIVE'),
    (30, 'Victoria''s Secret', 'Thương hiệu thời trang và nước hoa cơ thể gợi cảm lãng mạn trứ danh nước Mỹ thu hút mọi ánh nhìn.', 'ACTIVE');
