    (7, 'Sữa rửa mặt', 1, 'Sữa rửa mặt dạng gel, bọt dịu nhẹ làm sạch sâu không khô căng', 'ACTIVE'),
    (8, 'Kem chống nắng', 1, 'Kem và sữa chống nắng phổ rộng bảo vệ da trước tia UVA/UVB và ánh sáng xanh', 'ACTIVE'),
    (9, 'Nước hoa hồng & Toner', 1, 'Toner cân bằng độ pH, cấp ẩm tức thì và se khít lỗ chân lông', 'ACTIVE'),
    (10, 'Tẩy trang', 1, 'Nước, dầu và sáp tẩy trang làm sạch 99% bụi mịn và lớp makeup', 'ACTIVE'),
    (11, 'Tẩy tế bào chết', 1, 'Tẩy tế bào chết vật lý và hóa học AHA/BHA làm mịn màng bề mặt da', 'ACTIVE'),
    (12, 'Mặt nạ dưỡng da', 1, 'Mặt nạ giấy, mặt nạ đất sét thanh lọc và mặt nạ ngủ tái sinh', 'ACTIVE'),
    (13, 'Son môi', 2, 'Son thỏi lì, son kem nhung, son tint bóng và son dưỡng phục hồi môi', 'ACTIVE'),
