    (15, 'Phấn phủ & Má hồng', 2, 'Phấn phủ kiềm dầu lâu trôi và phấn má tươi tắn bắt sáng rạng ngời', 'ACTIVE'),
    (16, 'Trang điểm mắt & Mascara', 2, 'Mascara làm dài cong mi, kẻ mắt chống trôi và bảng phấn mắt cuốn hút', 'ACTIVE'),
    (17, 'Tẩy tế bào chết cơ thể', 3, 'Tẩy da chết toàn thân hạt cà phê, muối khoáng và đường hạt làm sáng da', 'ACTIVE'),
