INSERT INTO products (id, brand_id, category_id, name, description, origin, main_ingredients, benefits, is_featured, status, created_at) VALUES
    (1, 1, 5, 'Serum Bí Đao Cocoon 7% Niacinamide Trị Mụn & Mờ Thâm', 'Serum bí đao Cocoon kết hợp dịch chiết bí đao, rau má và tràm trà giúp kháng khuẩn, làm thông thoáng lỗ chân lông, kiềm dầu thừa rõ rệt.', 'Việt Nam', 'Bí đao, Rau má, Tràm trà, 7% Niacinamide, TECA', 'Kiểm soát dầu thừa, giảm sưng đỏ nốt mụn, làm mờ vết thâm mụn và ngăn ngừa mụn tái phát.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (2, 3, 5, 'Tinh Chất The Ordinary Niacinamide 10% + Zinc 1%', 'Công thức serum kinh điển chứa vitamin B3 nồng độ cao kết hợp kẽm khoáng giúp thanh lọc da, giảm bít tắc bã nhờn và đều màu da.', 'Canada', '10% Niacinamide, 1% Zinc PCA, Pentylene Glycol', 'Cân bằng bã nhờn, thu nhỏ lỗ chân lông, làm dịu da mụn và cải thiện bề mặt da mịn màng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (3, 2, 5, 'Serum Phục Hồi Tái Tạo Da La Roche-Posay Hyalu B5', 'Dưỡng chất chuyên sâu với phức hợp Hyaluronic Acid đa phân tử và Vitamin B5 đậm đặc giúp làm đầy nếp nhăn và tái tạo hàng rào da.', 'Pháp', 'Vitamin B5 (Panthenol), Dual Hyaluronic Acid, Madecassoside', 'Cấp ẩm chuyên sâu, phục hồi màng bảo vệ da bị tổn thương sau mụn hoặc liệu trình da liễu.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (4, 5, 5, 'Serum Cấp Ẩm Chuyên Sâu Innisfree Green Tea Seed Hyaluronic', 'Công nghệ thẩm thấu nano giúp dưỡng chất từ mầm trà xanh hữu cơ đảo Jeju khóa ẩm suốt 24 giờ cho làn da mọng nước.', 'Hàn Quốc', 'Trà xanh hữu cơ Beauty Green Tea, 5 loại Hyaluronic Acid', 'Cấp nước tức thì, giải cứu làn da khô ráp, củng cố độ đàn hồi và tạo độ bóng khỏe tự nhiên.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (5, 8, 5, 'Serum Siêu Cấp Ẩm & Sáng Mịn Da L''Oréal Paris Pure Hyaluronic Acid 1.5%', 'Serum dưỡng ẩm bán chạy toàn cầu với 1.5% Hyaluronic Acid phân tử siêu vi thẩm thấu sâu đa tầng biểu bì.', 'Pháp', '1.5% Hyaluronic Acid đa phân tử, Glycerin, Calcium Pantothenate', 'Làm đầy nếp nhăn li ti, giúp da căng mọng rạng rỡ và giữ ẩm suốt ngày dài.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (6, 13, 5, 'Serum Chống Lão Hóa Ban Đêm Estée Lauder Advanced Night Repair', 'Tinh chất ban đêm bán chạy số 1 tại Mỹ ứng dụng công nghệ Chronolux Power Signal phục hồi tối đa dấu hiệu tuổi tác.', 'Mỹ', 'Chronolux Power Signal, Men Bifida Ferment Lysate, Tripeptide-32', 'Giảm nếp nhăn rõ rệt, săn chắc đàn hồi và đánh thức làn da tươi trẻ rạng rỡ sau mỗi giấc ngủ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (7, 15, 5, 'Serum Dưỡng Sáng Da Mờ Thâm Nám Klairs Freshly Juiced Vitamin Drop', 'Serum Vitamin C tươi nồng độ 5% chiết xuất từ cam quýt hữu cơ an toàn cho làn da nhạy cảm dễ kích ứng.', 'Hàn Quốc', '5% Pure Vitamin C (Ascorbic Acid), Chiết xuất Rau má Centella', 'Làm mờ vết thâm sau mụn, ức chế melanin, làm đều màu da và kích thích sản sinh collagen.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (8, 18, 5, 'Tinh Chất Tái Tạo Da Kiehl''s Retinol Skin-Renewing Daily Micro-Dose', 'Công thức vi liều chuẩn xác kết hợp Retinol nguyên chất, Peptide và Ceramide giúp da tái tạo mịn màng không bong tróc.', 'Mỹ', 'Pure Retinol Micro-Dose, Niacinamide, Peptide, Ceramide', 'Tăng sinh collagen, xóa mờ nếp nhăn, thu nhỏ lỗ chân lông và làm mịn kết cấu da.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (9, 12, 5, 'Dưỡng Chất Khoáng Cô Đặc Phục Hồi Da Vichy Minéral 89 Booster', 'Chứa đến 89% nước khoáng núi lửa cô đặc giàu khoáng chất kết hợp 0.4% Hyaluronic Acid tự nhiên.', 'Pháp', '89% Vichy Thermal Water, Hyaluronic Acid, Citric Acid', 'Củng cố hàng rào bảo vệ da, tái tạo sức sống cho làn da xỉn màu và mất nước.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (10, 17, 5, 'Tinh Chất Giảm Thâm Nám Sáng Da Eucerin Spotless Brightening Booster Serum', 'Hoạt chất Thiamidol độc quyền được chứng minh lâm sàng ức chế enzyme Tyrosinase gây thâm nám từ gốc.', 'Đức', 'Thiamidol, Pro-Hyaluron đa tầng, Glucosylrutin', 'Giảm đốm nâu và thâm nám đến 75% sau 2 tuần, mang lại làn da trắng hồng rạng rỡ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (11, 4, 5, 'Tinh Chất Cấp Ẩm Chống Lão Hóa Paula''s Choice Hyaluronic Acid Booster', 'Serum đậm đặc chứa Hyaluronic Acid kết hợp Ceramide củng cố màng ẩm tức thì cho làn da mất nước.', 'Mỹ', 'Hyaluronic Acid phân tử nhỏ, Ceramide NP, Panthenol', 'Khôi phục độ ẩm ẩm mượt, xóa mờ nếp nhăn li ti và làm đầy rãnh cười.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (12, 19, 5, 'Tinh Chất Khởi Đầu Đánh Thức Làn Da Sulwhasoo First Care Activating Serum', 'Hợp chất Jaum Activator từ 5 loại thảo mộc Đông y quý hiếm tối ưu hóa khả năng hấp thụ dưỡng chất.', 'Hàn Quốc', 'Jaum Activator, Rễ Địa Hoàng, Hoa Mẫu Đơn, Hạt Sen Trắng', 'Kích hoạt tuần hoàn máu dưới da, tái sinh năng lượng và tăng cường hàng rào ẩm tự nhiên.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (13, 2, 5, 'Serum Trị Mụn Chuyên Sâu La Roche-Posay Effaclar Serum 3 Tác Động', 'Phức hợp 3 acid AHA + BHA + LHA kết hợp Niacinamide đặc trị mụn sưng viêm, mụn ẩn và vết thâm mụn dai dẳng.', 'Pháp', '1.5% Salicylic Acid (BHA), 3.5% Glycolic Acid (AHA), 0.45% LHA, Niacinamide', 'Tẩy tế bào chết sâu trong nang lông, giảm viêm sưng mụn mủ và se khít lỗ chân lông.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (14, 16, 5, 'Serum Cấp Nước Tươi Mát Simple Booster Serum 3% Hyaluronic Acid & B5', 'Công thức lành tính thuần chay không cồn, không paraben, cấp nước tức thì cho làn da nhạy cảm mất nước.', 'Anh', '3% Hyaluronic Acid, Vitamin B5, Pentavitin tự nhiên', 'Dưỡng ẩm mịn mượt, giảm khô ráp bong tróc mà hoàn toàn không gây nhờn dính.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (15, 20, 5, 'Serum Trẻ Hóa Tế Bào Cao Cấp Dior Capture Totale Le Sérum', 'Tuyệt tác chống lão hóa từ vườn hoa Dior Granville giúp phục hồi mật độ và độ săn chắc của làn da sau 4 giờ.', 'Pháp', 'Chiết xuất Hoa Longoza lên men, H.A. phân tử kép, Squalane thực vật', 'Làm mờ nếp nhăn sâu, nâng cơ và đem lại làn da trẻ trung tràn đầy sinh khí.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (16, 2, 6, 'Kem Dưỡng Ẩm Phục Hồi Da La Roche-Posay Cicaplast Baume B5+', 'Kem dưỡng phục hồi màng ẩm đa năng chứa Tribioma và 5% Panthenol làm dịu kích ứng và phục hồi sau 1 giờ.', 'Pháp', 'Tribioma, 5% Panthenol, Madecassoside, Zinc Gluconate', 'Làm dịu vết đỏ, giảm ngứa ngáy, phục hồi da tổn thương sau lăn kim, laser hoặc trị mụn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (17, 6, 6, 'Sữa Dưỡng Ẩm Chuyên Sâu CeraVe Moisturizing Lotion Da Khô', 'Sữa dưỡng ẩm dịu nhẹ dạng lỏng chứa 3 Ceramide thiết yếu ứng dụng công nghệ nhả chậm MVE suốt 24 giờ.', 'Mỹ', '3 Ceramide thiết yếu (1, 3, 6-II), Hyaluronic Acid, Công nghệ MVE', 'Phục hồi lớp màng bảo vệ tự nhiên, dưỡng ẩm sâu không gây bết rít cho mặt và cơ thể.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (18, 15, 6, 'Kem Dưỡng Ẩm Làm Dịu Da Khô & Nhạy Cảm Klairs Rich Moist Soothing Cream', 'Kem dưỡng ẩm lành tính từ nấm men Beta-Glucan và bơ hạt mỡ hạ nhiệt tức thì cho làn da căng rát.', 'Hàn Quốc', 'Chiết xuất Beta-Glucan, Dầu Jojoba hữu cơ, Bơ hạt mỡ', 'Cung cấp độ ẩm tức thì và duy trì độ ẩm bền vững cho làn da khô nhạy cảm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (19, 5, 6, 'Kem Dưỡng Cấp Nước Trà Xanh Innisfree Green Tea Seed Hyaluronic Cream', 'Kem dưỡng dạng gel cream tươi mát chứa mầm trà xanh hữu cơ giúp khóa chặt lớp ẩm suốt cả ngày.', 'Hàn Quốc', 'Beauty Green Tea, 5 loại Hyaluronic Acid, Ceramide trà xanh', 'Khóa ẩm đa tầng, nuôi dưỡng làn da căng mọng bóng bẩy chuẩn phong cách Hàn Quốc.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (20, 18, 6, 'Kem Dưỡng Ẩm Huyền Thoại Kiehl''s Ultra Facial Cream Suốt 24 Giờ', 'Kem dưỡng ẩm số 1 của Kiehl''s kết cấu siêu mỏng nhẹ với chiết xuất đạm Glycoprotein từ băng Bắc Cực.', 'Mỹ', 'Antarcticine (Đạm băng Bắc Cực), Squalane ô liu, Dầu quả bơ', 'Cấp ẩm sâu suốt 24 giờ kể cả trong điều kiện thời tiết khô hanh khắc nghiệt nhất.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (21, 9, 6, 'Kem Dưỡng Cấp Nước Khóa Ẩm Laneige Water Bank Blue Hyaluronic Cream', 'Công nghệ Blue Hyaluronic Acid siêu phân tử nhỏ hơn 2000 lần thẩm thấu siêu tốc vào hạ bì.', 'Hàn Quốc', 'Blue Hyaluronic Acid lên men sâu, Beta-glucan, Ceramide', 'Khắc phục 10 dấu hiệu da mất nước, giảm mẩn đỏ và phục hồi da nhạy cảm sau mụn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (22, 1, 6, 'Thạch Bí Đao Cocoon Cấp Ẩm Kiềm Dầu Mụn 100ml', 'Thạch dưỡng ẩm thuần chay kết cấu gel trong veo tan như nước trên da, kiểm soát nhờn suốt 24h.', 'Việt Nam', 'Chiết xuất bí đao, 5% Niacinamide, Tinh dầu tràm trà, L-Arginine', 'Kiềm dầu, làm dịu vết mụn sưng, dưỡng ẩm mỏng nhẹ không bít tắc nang lông.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (23, 17, 6, 'Kem Dưỡng Ẩm Cân Bằng Dịu Nhẹ Eucerin Lipo-Balance Da Khô Nhạy Cảm', 'Công thức chứa Ceramide-3 và Biotin giúp củng cố lớp lipid biểu bì ngăn mất nước qua da.', 'Đức', 'Ceramide-3, Biotin, Dầu bơ hạt mỡ, Vitamin E', 'Giảm khô ráp ngứa ngáy đến 90%, tăng khả năng đề kháng cho da nhạy cảm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (24, 16, 6, 'Kem Dưỡng Ẩm Dịu Nhẹ Simple Kind To Skin Replenishing Rich Moisturiser', 'Kem dưỡng lành tính với Pro-Vitamin B5 và Vitamin E nuôi dưỡng da suốt 12 giờ không bí da.', 'Anh', 'Pro-Vitamin B5, Vitamin E, Dầu hạt lưu ly borage seed oil', 'Khóa ẩm nhẹ nhàng, cân bằng sinh thái da, an toàn tuyệt đối cho mẹ bầu và da nhạy cảm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (25, 14, 6, 'Kem Dưỡng Kiềm Dầu Thu Nhỏ Lỗ Chân Lông Bioderma Sébium Pore Refiner', 'Hợp chất Fluidactiv độc quyền điều hòa lượng bã nhờn ngăn ngừa bít tắc lỗ chân lông.', 'Pháp', 'Phức hợp Fluidactiv, Axit Agaric, Bột khoáng kiềm dầu', 'Làm mịn bề mặt da, kiềm dầu đến 8 giờ và tạo hiệu ứng mịn lì tự nhiên.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (26, 8, 6, 'Kem Dưỡng Chống Lão Hóa Ban Đêm L''Oréal Paris Revitalift Laser X3', 'Công thức Pro-Xylane 3% nồng độ cao kích thích tổng hợp sợi collagen làm mờ nếp nhăn rõ rệt.', 'Pháp', '3% Pro-Xylane đậm đặc, Adenosine, LHA nhẹ nhàng', 'Tái tạo bề mặt da, nâng cơ săn chắc và phục hồi độ đàn hồi sau 4 tuần.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (27, 19, 6, 'Kem Dưỡng Nhân Sâm Hoàng Gia Sulwhasoo Concentrated Ginseng Renewing Cream', 'Chiết xuất Ginsenomics cô đặc gấp 6000 lần từ sâm quý Hàn Quốc tái sinh mật độ cấu trúc tế bào da.', 'Hàn Quốc', 'Ginsenomics, Chiết xuất củ sâm đỏ 6 năm tuổi, Peptides sâm', 'Xóa mờ rãnh nhăn sâu, tăng độ săn chắc và đem lại làn da sáng mịn căng tràn sức sống.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (28, 4, 6, 'Kem Dưỡng Ẩm Đêm Cho Da Dầu Mụn Paula''s Choice Clear Oil-Free Moisturizer', 'Kem dưỡng không chứa dầu khoáng kết hợp Niacinamide và Ceramide cấp ẩm mà không gây mụn.', 'Mỹ', 'Niacinamide, Ceramide, Chiết xuất Cam thảo, Blueberry', 'Làm dịu nốt mụn đỏ, cấp ẩm dịu mát và tăng cường hàng rào kháng khuẩn cho da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (29, 12, 6, 'Gel Dưỡng Ẩm Khóa Nước Suốt 48 Giờ Vichy Aqualia Thermal Gel Cream', 'Chứa nước khoáng núi lửa Vichy và đường thực vật Mannose cấp nước sâu từng tế bào biểu bì.', 'Pháp', 'Vichy Thermal Water, Sodium Hyaluronate, Đường Mannose', 'Khóa ẩm suốt 48 giờ, tạo màng mỏng mịn như sương mát lạnh trên làn da thiếu nước.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (30, 2, 6, 'Kem Dưỡng Làm Giảm Mụn Đầu Đen La Roche-Posay Effaclar K(+)', 'Kết hợp LHA, Salicylic Acid và phức hợp Carnosine + Vitamin E chống oxy hóa bã nhờn suốt 8 giờ.', 'Pháp', 'LHA, Salicylic Acid, Carnosine, Airlicium', 'Loại bỏ mụn đầu đen, kiềm dầu thừa, làm mịn màng kết cấu da gồ ghề sau 2 tuần.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (31, 1, 7, 'Sữa Rửa Mặt Dịu Nhẹ Cocoon Cà Phê Đắk Lắk Sạch Sâu', 'Chiết xuất cà phê Đắk Lắk nguyên chất kết hợp dầu mù u và acid amin làm sạch dịu nhẹ không khô căng.', 'Việt Nam', 'Chiết xuất cà phê Đắk Lắk, Dầu mù u, Axit Amin, Vitamin B5', 'Làm sạch sâu bã nhờn và bụi bẩn, giữ màng ẩm tự nhiên ở độ pH chuẩn 5.5.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (32, 6, 7, 'Sữa Rửa Mặt Tạo Bọt CeraVe Foaming Facial Cleanser Cho Da Dầu Mụn', 'Sữa rửa mặt dạng gel tạo bọt mịn cuốn trôi dầu thừa và cặn trang điểm mà không làm căng rát da.', 'Mỹ', '3 Ceramide thiết yếu, Niacinamide, Hyaluronic Acid', 'Thanh lọc tuyến bã nhờn, bảo vệ hàng rào lipid tự nhiên của biểu bì.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (33, 2, 7, 'Gel Rửa Mặt Làm Sạch Sâu Giảm Nhờn La Roche-Posay Effaclar Purifying Foaming Gel', 'Gel rửa mặt chuyên biệt cho da dầu nhạy cảm với kẽm PCA kháng khuẩn và nước khoáng La Roche-Posay.', 'Pháp', 'Nước khoáng La Roche-Posay, Zinc PCA, Citric Acid', 'Loại bỏ tạp chất và dầu thừa tận sâu chân lông, giảm bóng nhờn suốt ngày dài.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (34, 5, 7, 'Sữa Rửa Mặt Trà Xanh Dưỡng Ẩm Innisfree Green Tea Hydrating Amino Cleansing Foam', 'Bọt amino acid siêu mịn từ trà xanh hữu cơ làm sạch êm ái mà vẫn giữ lại độ ẩm mượt tự nhiên.', 'Hàn Quốc', 'Chiết xuất trà xanh Beauty Green Tea, Phức hợp Amino Acid', 'Làm sạch dịu mát, đánh thức làn da sảng khoái tràn đầy năng lượng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (35, 16, 7, 'Gel Rửa Mặt Dịu Nhẹ Simple Kind To Skin Refreshing Facial Wash 100% Soap Free', 'Gel rửa mặt quốc dân không chứa xà phòng, không chất tạo màu nhân tạo an toàn cho mọi làn da.', 'Anh', 'Pro-Vitamin B5, Vitamin E, Nước tinh khiết lọc 3 lần', 'Rửa sạch nhẹ dịu, duy trì lớp màng bảo vệ tự nhiên không gây kích ứng đỏ rát.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (36, 6, 7, 'Sữa Rửa Mặt Dưỡng Ẩm CeraVe Hydrating Facial Cleanser Cho Da Khô', 'Công thức dạng sữa không bọt làm sạch nhẹ nhàng và bù ẩm tức thì cho làn da nứt nẻ nhạy cảm.', 'Mỹ', '3 Ceramide thiết yếu, Hyaluronic Acid, Glycerin thực vật', 'Cân bằng độ ẩm sinh học, bảo tồn tối đa lớp màng lipid tự nhiên của da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (37, 18, 7, 'Sữa Rửa Mặt Hoa Cúc Làm Dịu Da Kiehl''s Calendula Deep Cleansing Foaming', 'Chiết xuất hoa cúc La Mã Marigold tạo bọt bông mịn cuốn trôi bụi bẩn mà giữ da êm ái thư giãn.', 'Mỹ', 'Chiết xuất Hoa cúc Calendula, Glycerin nguồn gốc tự nhiên', 'Làm dịu làn da kích ứng, kháng viêm nhẹ và se mịn bề mặt da.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (38, 14, 7, 'Gel Rửa Mặt Làm Sạch Dịu Nhẹ Cho Da Nhạy Cảm Bioderma Sensibio Gel Moussant', 'Phức hợp DAF tự nhiên được cấp bằng sáng chế giúp tăng ngưỡng dung nạp của làn da nhạy cảm.', 'Pháp', 'Phức hợp D.A.F, Coco-Glucoside, Glyceryl Oleate', 'Làm sạch nhẹ nhàng, dưỡng ẩm và làm dịu ngay cảm giác ngứa căng rát.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (39, 12, 7, 'Gel Rửa Mặt Trị Mụn Kiềm Dầu Sâu Vichy Normaderm Phytosolution', 'Kết hợp Kẽm, Đồng khoáng và BHA tự nhiên từ cây lộc đề giúp làm sạch bã nhờn và ngừa mụn.', 'Pháp', 'Zinc Oxide, Copper, Salicylic Acid thực vật, Nước khoáng Vichy', 'Giảm bóng dầu 80%, ngăn ngừa bùng phát mụn viêm và thu nhỏ chân lông.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (40, 17, 7, 'Gel Rửa Mặt Giảm Mụn Cho Da Nhờn Eucerin Pro Acne Solution Cleansing Gel', 'Công thức không xà phòng, không hương liệu chứa 6% Ampho-Tensides làm sạch bã nhờn dịu nhẹ.', 'Đức', '6% Ampho-Tensides, Salicylic Acid, Citric Acid', 'Tẩy sạch bã nhờn dư thừa, ngăn chặn vi khuẩn gây mụn P.acnes phát triển.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (41, 15, 7, 'Sữa Rửa Mặt Tạo Bọt Dịu Nhẹ Klairs Rich Moist Foaming Cleanser', 'Công thức tạo bọt tự nhiên với amino acid thay thế chất hoạt động bề mặt SLS mạnh.', 'Hàn Quốc', 'Axit Amin thực vật, Ceramide 3, Dầu tràm trà hữu cơ', 'Làm sạch sâu nhẹ nhàng, cấp nước cho làn da khô nhạy cảm dễ kích ứng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (42, 4, 7, 'Sữa Rửa Mặt Phục Hồi Hàng Rào Ẩm Paula''s Choice Resist Optimal Results', 'Kết cấu sữa mịn như kem giúp bảo vệ lớp lipid bảo vệ da trong lúc loại bỏ lớp trang điểm nhẹ.', 'Mỹ', 'Chiết xuất Trà xanh, Cúc La Mã, Glycerin thực vật', 'Chống lão hóa, làm dịu da khô ngứa và duy trì độ ẩm mịn màng mượt mà.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (43, 1, 7, 'Gel Rửa Mặt Hoa Hồng Cocoon Cấp Ẩm Da Mềm Mượt 140ml', 'Nước cất hoa hồng hữu cơ Hậu Giang kết hợp Betaine và Allantoin làm sạch dịu ngọt da khô.', 'Việt Nam', 'Nước cất hoa hồng hữu cơ, Betaine, Allantoin', 'Cấp ẩm sâu, se nhỏ lỗ chân lông và lưu lại làn da mềm mại ngát hương hoa.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (44, 26, 7, 'Xà Phòng Rửa Mặt Dưỡng Ẩm Tinh Chất Oliu DHC Mild Soap 90g', 'Bánh xà phòng rửa mặt truyền thống Nhật Bản giàu dầu olive nguyên chất và mật ong tinh khiết.', 'Nhật Bản', 'Dầu Olive nguyên chất hữu cơ, Mật ong tự nhiên', 'Tạo lớp bọt xốp dày đặc cuốn trôi bã nhờn mà da vẫn mềm mịn mượt mà.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (45, 8, 7, 'Sữa Rửa Mặt Sáng Mịn & Căng Mướt L''Oréal Paris Glycolic-Bright Glowing Foam', 'Chứa Glycolic Acid (AHA) nồng độ nhẹ nhàng tẩy tế bào chết xỉn màu ngay trong bước rửa mặt.', 'Pháp', 'Glycolic Acid (AHA), Bọt khoáng mịn, Niacinamide', 'Làm sáng làn da sạm màu, làm mờ vết thâm nám và mang lại vẻ tươi sáng đều màu.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (46, 2, 8, 'Kem Chống Nắng Kiềm Dầu La Roche-Posay Anthelios UVMune 400 Oil Control', 'Đột phá màng lọc Mexoryl 400 chống tia UVA dài nhất (380-400nm), kết hợp công nghệ Airlicium kiềm dầu đến 12 giờ.', 'Pháp', 'Màng lọc Mexoryl 400, Hoạt chất Airlicium, Nước khoáng LRP', 'Bảo vệ toàn diện trước tia UV nguy hại, kháng nước kháng mồ hôi, ráo mịn không vệt trắng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (47, 7, 8, 'Sữa Chống Nắng Dưỡng Da Kiềm Dầu Anessa Perfect UV Sunscreen Skincare Milk SPF50+', 'Công nghệ Auto Booster độc quyền phản ứng với nhiệt độ, độ ẩm và mồ hôi để màng bảo vệ càng thêm bền bỉ.', 'Nhật Bản', 'Công nghệ Auto Booster, Chiết xuất Trà xanh Kyoto, Collagen', 'Chống trôi cực hạn khi đi bơi hay hoạt động ngoài trời, dưỡng ẩm chống oxy hóa da.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (48, 25, 8, 'Sữa Chống Nắng Hiệu Chỉnh Sắc Da Skin Aqua Tone Up UV Milk Lavender', 'Sắc tím Lavender hòa quyện giữa sắc xanh và hồng giúp hiệu chỉnh tone da vàng vọt sáng bừng rạng rỡ.', 'Nhật Bản', 'Hyaluronic Acid, Vitamin C, Chiết xuất Chanh Dây, Mận châu Âu', 'Nâng tone da tự nhiên bắt sáng trong trẻo, kiểm soát bã nhờn dịu nhẹ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (49, 12, 8, 'Kem Chống Nắng Kiềm Dầu Khô Thoáng Vichy Capital Soleil Mattifying Dry Touch', 'Công nghệ màng lọc Mexoryl XL kết hợp đất sét xanh Pháp giúp hấp thu bã nhờn tức thì suốt cả ngày.', 'Pháp', 'Màng lọc Mexoryl XL, Đất sét xanh Kaolin, Nước khoáng núi lửa Vichy', 'Kiềm dầu khô thoáng, bảo vệ tế bào da trước tia UV và ô nhiễm khói bụi thành thị.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (50, 5, 8, 'Kem Chống Nắng Kiềm Dầu Nâng Tone Innisfree Tone Up No Sebum Sunscreen', 'Bộ lọc khoáng chất vô cơ vật lý lành tính kết hợp bột kiềm dầu No-Sebum kiềm dầu 24h.', 'Hàn Quốc', 'Zinc Oxide, Titanium Dioxide, Chiết xuất rau má, Trà xanh', 'Bảo vệ da dịu nhẹ, nâng tone hồng hào tự nhiên thay thế lớp kem lót trang điểm.', 0, 'ACTIVE', '2026-01-01 00:00:00');
INSERT INTO products (id, brand_id, category_id, name, description, origin, main_ingredients, benefits, is_featured, status, created_at) VALUES
    (51, 17, 8, 'Kem Chống Nắng Cho Da Dầu Mụn Eucerin Sun Gel-Cream Dry Touch Oil Control', 'Công nghệ quang phổ tiên tiến kết hợp L-Carnitine kiểm soát bã nhờn suốt 8 giờ không bóng dầu.', 'Đức', 'L-Carnitine, Licochalcone A, Glycyrrhetinic Acid', 'Bảo vệ DNA tế bào da, chống lại tác hại của tia HEVIS (ánh sáng xanh từ màn hình).', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (52, 8, 8, 'Serum Chống Nắng Mịn Mờ Vệt Bóng L''Oréal Paris UV Defender Matte & Fresh', 'Màng lọc quang phổ rộng Mexoryl SX/XL kết hợp khoáng chất Airlicium cho bề mặt ráo mịn như nhung.', 'Pháp', 'Màng lọc Mexoryl SX/XL, Khoáng chất Airlicium, Niacinamide', 'Cản tia UV tối đa, ngăn ngừa 5 năm lão hóa do ánh nắng mặt trời.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (53, 4, 8, 'Kem Chống Nắng Toàn Diện Paula''s Choice Extra Care Non-Greasy Sunscreen SPF 50', 'Chống nắng thể thao kháng nước lâu trôi cho mặt và toàn thân với kết cấu mỏng mịn thấm nhanh.', 'Mỹ', 'Hợp chất chống oxy hóa Vitamin A, C, E, Màng lọc chống nắng thế hệ mới', 'Chống nắng phổ rộng bảo vệ da khi đi bơi hay chơi thể thao ngoài trời.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (54, 1, 8, 'Sữa Chống Nắng Bí Đao Cocoon Kháng Nước & Kiềm Dầu 50ml', 'Chống nắng thuần chay quang phổ rộng chứa chiết xuất bí đao và Vitamin B3 bảo vệ da mụn.', 'Việt Nam', 'Chiết xuất bí đao, 4% Niacinamide, Tinosorb S, Uvinul A Plus', 'Bảo vệ da mụn nhạy cảm, giảm tiết dầu và không gây bít tắc sinh mụn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (55, 18, 8, 'Kem Chống Nắng Thoáng Nhẹ Kiehl''s Ultra Light Daily UV Defense SPF 50', 'Kết cấu gel nước mỏng nhẹ không dầu giúp bảo vệ da trước tia UV và bụi mịn ô nhiễm PM 2.5.', 'Mỹ', 'Chiết xuất rễ cây Hoàng Cầm Baicalin, Vitamin E, Màng lọc Mexoryl', 'Ngăn ngừa đốm nâu nám da và các dấu hiệu lão hóa sớm do môi trường đô thị.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (56, 14, 8, 'Kem Chống Nắng Cho Da Dầu Mụn Bioderma Photoderm AKN Mat SPF 30', 'Sáng chế độc quyền Fluidactiv sinh học giúp duy trì chất lượng bã nhờn tự nhiên không bị oxy hóa đặc quánh.', 'Pháp', 'Phức hợp Fluidactiv, Bột Silica kiềm dầu, Axit Glycolic', 'Ngăn chặn hiệu ứng bùng phát mụn trở lại sau khi ngưng đi nắng (Rebound Effect).', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (57, 7, 8, 'Gel Chống Nắng Dưỡng Ẩm Mát Lạnh Anessa Perfect UV Sunscreen Skincare Gel', 'Kết cấu gel ẩm mượt chứa 50% thành phần dưỡng da giúp làn da luôn ngậm nước căng mọng.', 'Nhật Bản', 'Collagen biển, Chiết xuất hoa cúc vàng, Hyaluronic Acid', 'Bảo vệ da khô mất nước, tạo lớp lót ẩm mịn cho lớp trang điểm bám đều tự nhiên.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (58, 26, 8, 'Kem Chống Nắng Trắng Da DHC Suncut Q10 EX SPF50+ PA++++', 'Bổ sung hoạt chất Coenzyme Q10 và dầu Oliu đậm đặc chống lại quá trình oxy hóa tế bào da.', 'Nhật Bản', 'Coenzyme Q10, Dầu Oliu nguyên chất, Tinh chất rong biển Laminaria', 'Dưỡng trắng da, ngăn ngừa tàn nhang và giữ ẩm mềm mại.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (59, 19, 8, 'Kem Chống Nắng Dưỡng Trắng Đông Y Sulwhasoo UV Wise Brightening Multi Protector', 'Phức hợp Wowsome Formula và tinh chất Bạch sâm bảo vệ da trước tia UV và nhiệt độ cao sinh nhiệt nám.', 'Hàn Quốc', 'Tinh chất Bạch Sâm, Rễ Dâu Tằm, Màng lọc Nano vô cơ', 'Hạ nhiệt làm dịu da, ngăn ngừa sạm nám tận gốc và đem lại làn da sáng mịn rạng ngời.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (60, 2, 8, 'Xịt Chống Nắng Kiềm Dầu Tiện Lợi La Roche-Posay Anthelios Anti-Shine Mist', 'Xịt chống nắng phun sương siêu mịn giúp dặm lại kem chống nắng tiện lợi bên trên lớp trang điểm.', 'Pháp', 'Màng lọc Mexoryl XL, Khoáng chất Airlicium, Nước khoáng LRP', 'Không cần chạm tay, kiềm dầu tức thì và bảo vệ da liên tục cả ngày dài.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (61, 15, 9, 'Nước Hoa Hồng Cấp Ẩm Không Mùi Klairs Supple Preparation Unscented Toner', 'Toner quốc dân thuần chay không cồn, không hương liệu, cân bằng độ pH tức thì và cấp ẩm sâu.', 'Hàn Quốc', 'Hyaluronic Acid, Chiết xuất rau má, Phyto-Oligo, Lipidure-PMB', 'Làm dịu da kích ứng, cân bằng độ ẩm và mở đường cho tinh chất hấp thụ tối đa.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (62, 12, 9, 'Xịt Khoáng Dưỡng Da Làm Dịu Tức Thì Vichy Mineralizing Thermal Spa Water', '100% nước khoáng núi lửa Pháp nguyên chất chứa 15 khoáng chất quý hiếm củng cố hàng rào phòng vệ.', 'Pháp', '100% Nước khoáng núi lửa Pháp tự nhiên', 'Làm dịu mát tức thì, hạ nhiệt độ da khi đi nắng và bảo vệ da trước ô nhiễm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (63, 18, 9, 'Nước Cân Bằng Hoa Cúc Cánh Tươi Kiehl''s Calendula Herbal-Extract Toner', 'Toner chứa những cánh hoa cúc vạn thọ tươi được hái thủ công bằng tay giúp làm dịu và kháng viêm da.', 'Mỹ', 'Cánh hoa cúc Calendula tươi, Allantoin, Chiết xuất rễ Ngưu Bàng', 'Cân bằng dầu thừa, làm dịu các nốt mụn đỏ sưng tấy và se khít lỗ chân lông.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (64, 1, 9, 'Nước Hoa Hồng Hậu Giang Cocoon Thu Nhỏ Lỗ Chân Lông & Cấp Ẩm', 'Nước cất hoa hồng hữu cơ kết hợp HA đa phân tử và men vi sinh giúp nuôi dưỡng hệ vi sinh vật có lợi cho da.', 'Việt Nam', 'Nước cất hoa hồng Hậu Giang, Hyaluronic Acid, Men vi sinh Betaine', 'Cấp ẩm sâu, se khít lỗ chân lông và làm mềm bề mặt da khô ráp.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (65, 16, 9, 'Nước Hoa Hồng Dịu Nhẹ Simple Kind To Skin Soothing Facial Toner', 'Công thức cân bằng lành tính chứa Pro-Vitamin B5, hoa cúc Chamomile và cây phỉ Witch Hazel.', 'Anh', 'Pro-Vitamin B5, Chiết xuất Hoa cúc Chamomile, Nước cây phỉ', 'Cân bằng độ pH, làm sạch sâu cặn bẩn còn sót lại mà da vẫn ẩm mượt không căng rát.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (66, 14, 9, 'Nước Hoa Hồng Dưỡng Ẩm Chuyên Sâu Cho Da Khô Bioderma Hydrabio Tonique', 'Sáng chế sinh học Aquagenium kích thích làn da tự sản sinh kênh dẫn nước Aquaporins tự nhiên.', 'Pháp', 'Phức hợp Aquagenium, Vitamin PP, Chiết xuất hạt táo Pyrus Malus', 'Tái tạo khả năng giữ ẩm tự nhiên của tế bào, mang lại làn da căng tràn rạng rỡ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (67, 5, 9, 'Nước Cân Bằng Trị Mụn & Se Lỗ Chân Lông Innisfree Bija Trouble Skin', 'Tinh dầu hạt Bija tự nhiên từ rừng Bija ngàn năm trên đảo Jeju với Salicylic Acid thực vật.', 'Hàn Quốc', 'Dầu hạt Bija Jeju, Salicylic Acid (BHA), Vỏ cây liễu trắng', 'Làm dịu nốt mụn viêm sưng, kháng khuẩn và thanh lọc lỗ chân lông bít tắc.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (68, 4, 9, 'Nước Hoa Hồng Kiềm Dầu & Thu Nhỏ Chân Lông Paula''s Choice Skin Balancing Toner', 'Công thức bổ sung Niacinamide và chất chống oxy hóa giúp điều tiết bã nhờn và phục hồi da dầu.', 'Mỹ', 'Niacinamide, Ceramide, Chiết xuất cúc La Mã Chamomile, Sodium Hyaluronate', 'Giảm bóng dầu, thu nhỏ lỗ chân lông giãn nở và cân bằng hàng rào bảo vệ ẩm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (69, 3, 9, 'Dung Dịch Tẩy Da Chết Làm Sáng Da The Ordinary Glycolic Acid 7% Toning Solution', 'Chứa 7% Glycolic Acid (AHA) kết hợp chiết xuất hạt tiêu Tasmania làm giảm kích ứng khi tẩy da chết.', 'Canada', '7% Glycolic Acid, Chiết xuất tiêu núi Tasmania, Nha đam, Nhân sâm', 'Tẩy sạch lớp sừng già cỗi, làm mờ thâm mụn, cho làn da bóng bẩy mịn màng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (70, 2, 9, 'Nước Hoa Hồng Giảm Dầu & Se Khít Lỗ Chân Lông La Roche-Posay Effaclar Astringent', 'Chứa hoạt chất LHA tẩy tế bào chết vi mô dịu nhẹ kết hợp nước khoáng nhiệt trị liệu.', 'Pháp', 'Capryloyl Salicylic Acid (LHA), Nước khoáng La Roche-Posay, Citric Acid', 'Thu nhỏ lỗ chân lông, ngăn chặn tích tụ bã nhờn gây mụn đầu đen.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (71, 17, 9, 'Nước Cân Bằng Cấp Ẩm Cho Da Nhạy Cảm Eucerin DermatoClean Hyaluron Toner', 'Phức hợp APG nhẹ nhàng làm sạch kết hợp Gluco-Glycerol và Hyaluronic Acid cấp ẩm sâu.', 'Đức', 'APG Complex, Hyaluronic Acid, Gluco-Glycerol', 'Giúp da thông thoáng, hô hấp tốt hơn và chuẩn bị tối ưu cho bước dưỡng tiếp theo.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (72, 1, 9, 'Toner Nghệ Hưng Yên Cocoon Dưỡng Sáng & Mờ Thâm 140ml', 'Chiết xuất nghệ Hưng Yên giàu curcuminoid kết hợp 5% Niacinamide phục hồi da thâm sạm.', 'Việt Nam', 'Chiết xuất củ nghệ Hưng Yên, 5% Niacinamide, Betaine', 'Làm sáng da xỉn màu, ức chế sắc tố melanin sau mụn và chống oxy hóa mạnh mẽ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (73, 8, 9, 'Nước Hoa Hồng Tươi Mát & Căng Mịn L''Oréal Paris Revitalift Aqua Milky Toner', 'Kết cấu sữa lỏng giàu tinh chất dưỡng ẩm giúp làn da mềm mượt ngay tức khắc.', 'Pháp', 'Hoạt chất Dermalift, Pro-Retinol A, Glycerin', 'Tăng cường độ đàn hồi, ngăn ngừa xuất hiện nếp nhăn sớm và cấp ẩm mịn màng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (74, 19, 9, 'Nước Cân Bằng Thiết Yếu Dưỡng Ẩm Sulwhasoo Essential Comfort Balancing Water', 'Công thức thảo mộc JAUM Moisturizing Complex làm dịu làn da mệt mỏi căng thẳng.', 'Hàn Quốc', 'JAUM Moisturizing Complex, Rễ Thược Dược, Hạt Sen Tươi', 'Cấp ẩm sâu êm dịu, khôi phục trạng thái mềm mượt thư thái cho làn da.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (75, 2, 9, 'Xịt Khoáng Làm Dịu & Giảm Bóng Nhờn La Roche-Posay Serozinc Zinc Sulfate', 'Công thức độc đáo chứa khoáng Kẽm Sunfat kháng viêm, giảm tiết bã nhờn tức thì cho da mụn.', 'Pháp', 'Kẽm Sunfat (Zinc Sulfate 0.10%), Muối khoáng NaCl, Nước tinh khiết LRP', 'Kiềm dầu, làm dịu nốt mụn sưng đỏ và bảo vệ bề mặt da khỏi vi khuẩn.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (76, 14, 10, 'Nước Tẩy Trang Dịu Nhẹ Cho Da Nhạy Cảm Bioderma Sensibio H2O', 'Nước tẩy trang công nghệ Micellar số 1 thế giới với hạt micelle sinh học tương thích làn da.', 'Pháp', 'Hạt Micelle sinh học, Chiết xuất dưa leo tự nhiên, Nước siêu tinh khiết', 'Làm sạch 99% lớp trang điểm và bụi mịn PM 2.5 mà hoàn toàn không cần rửa lại với nước.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (77, 8, 10, 'Nước Tẩy Trang Tươi Mát Kiềm Dầu L''Oréal Paris Micellar Water 3-in-1 Deep Cleansing', 'Công nghệ Bi-phase 2 lớp dầu và nước làm sạch tức thì kể cả mascara và son lì kháng nước.', 'Pháp', 'Hạt Micelle hút dầu, Nước khoáng ngầm Vosges Pháp, Dầu dưỡng nhẹ', 'Hòa tan lớp trang điểm cứng đầu chỉ với một lần lau, không gây nhờn dính.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (78, 1, 10, 'Dầu Tẩy Trang Hoa Hồng Cocoon Làm Sạch Sâu & Ẩm Mượt 140ml', 'Dầu tẩy trang thuần chay từ dầu hoa hồng hữu cơ và vitamin E nhũ hóa cực nhanh không gây mụn ẩn.', 'Việt Nam', 'Dầu hoa hồng hữu cơ Hậu Giang, Vitamin E, Tinh dầu hoa cúc', 'Hòa tan bã nhờn và cặn trang điểm trong lỗ chân lông, mang lại làn da mềm ẩm mịn màng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (79, 26, 10, 'Dầu Tẩy Trang Ô Liu Làm Sạch Sâu DHC Deep Cleansing Oil', 'Tuyệt tác làm sạch huyền thoại Nhật Bản chứa dầu oliu hữu cơ Flor de Aceite tinh khiết nhất.', 'Nhật Bản', 'Dầu Olive nguyên chất hữu cơ Tây Ban Nha, Dầu hương thảo, Vitamin E', 'Cuốn trôi mụn đầu đen, bã nhờn cứng đầu và lớp makeup dày cộm mà vẫn bảo vệ độ ẩm.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (80, 16, 10, 'Nước Tẩy Trang Dịu Nhẹ Cho Da Nhạy Cảm Simple Kind To Skin Micellar Water', 'Công thức dịu nhẹ chứa vitamin B3, vitamin C và nước tinh khiết làm sạch mà không làm khô da.', 'Anh', 'Hạt Micellar thông minh, Vitamin B3 (Niacinamide), Vitamin C, Nước cất', 'Tẩy sạch tạp chất và bụi bẩn hằng ngày nhẹ nhàng, không gây cay mắt.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (81, 2, 10, 'Nước Tẩy Trang Cho Da Dầu Nhạy Cảm La Roche-Posay Effaclar Micellar Water Ultra', 'Công nghệ cải tiến Glyco-Micellar kết hợp muối kẽm PCA làm sạch bã nhờn và tạp chất siêu tốc.', 'Pháp', 'Công nghệ Glyco-Micellar, Kẽm PCA, Nước khoáng La Roche-Posay', 'Giảm bóng dầu, duy trì độ pH sinh lý và ngăn ngừa hình thành mụn mới.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (82, 11, 10, 'Nước Tẩy Trang Mắt & Môi Chuyên Dụng Maybelline Eye & Lip Makeup Remover', 'Công thức 2 lớp dầu nước chuyên biệt hòa tan mascara chống trôi và son lì lì bám chặt.', 'Mỹ', 'Dầu dưỡng mi, Nước khoáng thanh khiết, Panthenol nuôi dưỡng mi', 'Tẩy sạch êm ái vùng da mắt môi nhạy cảm mà không cần chà xát mạnh gây rụng mi.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (83, 14, 10, 'Nước Tẩy Trang Kiềm Dầu Cho Da Dầu Mụn Bioderma Sébium H2O Nắp Xanh', 'Công nghệ Micellar kết hợp kẽm Gluconate và đồng Sulphate thanh lọc bã nhờn sâu trong lỗ chân lông.', 'Pháp', 'Hạt Micelle Sébium, Đồng Sulphate, Kẽm Gluconate, Ginkgo Biloba', 'Giảm bóng nhờn, ngăn ngừa mụn và giữ cho da thông thoáng cả ngày.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (84, 5, 10, 'Dầu Tẩy Trang Táo Xanh Sạch Sâu Innisfree Apple Seed Cleansing Oil', 'Dầu hạt táo xanh đảo Jeju giàu acid béo chưa bão hòa giúp làm tan chảy lớp trang điểm dày.', 'Hàn Quốc', 'Dầu hạt táo ép lạnh Jeju, Chiết xuất vỏ táo xanh tươi mát', 'Làm sạch mịn màng, thông thoáng lỗ chân lông với hương thơm táo ngọt ngào.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (85, 17, 10, 'Nước Tẩy Trang Cho Da Nhờn Mụn Eucerin Pro Acne Solution Micellar Water', 'Hợp chất làm sạch APG dịu nhẹ kết hợp Arginine làm dịu vết mụn viêm và giảm kích ứng da.', 'Đức', 'APG Complex, Arginine, Sodium Hyaluronate', 'Tẩy sạch bã nhờn dư thừa, ngăn ngừa mụn ẩn mà không làm khô căng hay rát da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (86, 1, 10, 'Nước Tẩy Trang Bí Đao Cocoon Làm Sạch Dầu Mụn 500ml', 'Nước tẩy trang thuần chay ứng dụng công nghệ NatraGem S140 kết hợp tràm trà kháng khuẩn.', 'Việt Nam', 'Chiết xuất bí đao, Tinh dầu tràm trà hữu cơ, 3% Niacinamide', 'Làm sạch dầu nhờn và lớp kem chống nắng, làm dịu vết đỏ của nốt mụn viêm.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (87, 15, 10, 'Dầu Tẩy Trang Làm Dịu Da Đen Tuyền Klairs Gentle Black Deep Cleansing Oil', 'Phức hợp 4 loại tinh dầu hạt thực vật đen (đậu đen, mè đen, hạt nho, dầu jojoba) giàu dưỡng chất.', 'Hàn Quốc', 'Dầu đậu đen lên men, Dầu mè đen hữu cơ, Dầu hạt nho, Dầu bơ hạt mỡ', 'Hút sạch bã nhờn và nhân mụn cám, cấp ẩm nuôi dưỡng bề mặt da mịn màng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (88, 4, 10, 'Sáp Tẩy Trang Làm Dịu Da Nhạy Cảm Paula''s Choice Omega+ Complex Cleansing Balm', 'Sáp tẩy trang tan mịn màng như dầu giàu phức hợp Omega 3-6-9 phục hồi màng lipid tế bào da.', 'Mỹ', 'Omega 3-6-9 Complex, Dầu hạt Meadowfoam, Dầu hạt Jojoba', 'Hòa tan lớp trang điểm dày cộm mà vẫn duy trì độ ẩm mịn mượt mà cho da nhạy cảm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (89, 18, 10, 'Dầu Tẩy Trang Thảo Mộc Ban Đêm Kiehl''s Midnight Recovery Botanical Cleansing Oil', 'Tinh dầu hoa dạ thảo, hoa oải hương và tinh dầu squalane giúp thanh lọc da và thư giãn tinh thần.', 'Mỹ', 'Tinh dầu Hoa dạ thảo Evening Primrose, Tinh dầu Lavender, Squalane', 'Làm sạch sâu tạp chất ban ngày, nuôi dưỡng da căng bóng ngậm nước vào ban đêm.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (90, 9, 10, 'Nước Tẩy Trang Cấp Nước Tươi Mới Laneige Water Bank Micellar Cleansing Water', 'Chứa Blue Hyaluronic Acid phân tử siêu nhỏ hút sạch bụi mịn bám sâu trong lỗ chân lông.', 'Hàn Quốc', 'Blue Hyaluronic Acid, Men nấm men Beta-Glucan, Dầu hạt Meadowfoam', 'Làm sạch dịu nhẹ không cần rửa lại, lưu lại độ ẩm mượt mát lành trên da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (91, 4, 11, 'Dung Dịch Tẩy Tế Bào Chết Hóa Học Paula''s Choice BHA 2% Liquid', 'Sản phẩm kinh điển chứa 2% BHA tan trong dầu giúp loại bỏ mụn đầu đen, bã nhờn tích tụ, đem lại bề mặt da mịn màng.', 'Mỹ', '2% Salicylic Acid (BHA), Chiết xuất Trà xanh Camellia Oleifera, Methylpropanediol', 'Loại bỏ tế bào chết sâu trong nang lông, cải thiện mụn ẩn và thu nhỏ chân lông.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (92, 3, 11, 'Tinh Chất Peel Da Tẩy Tế Bào Chết The Ordinary AHA 30% + BHA 2% Peeling Solution', 'Serum peel da màu đỏ đặc trưng kết hợp 30% AHA và 2% BHA giúp tái tạo bề mặt da láng mịn.', 'Canada', '30% AHA (Glycolic, Lactic, Tartaric, Citric), 2% BHA (Salicylic Acid), Cà rốt đen', 'Làm mờ vết thâm mụn, đều màu da và kích thích tái sinh tế bào biểu bì mới.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (93, 1, 11, 'Cà Phê Đắk Lắk Làm Sạch Da Chết Mặt Cocoon Dak Lak Coffee Face Polish', 'Hạt cà phê Đắk Lắk xay siêu mịn kết hợp bơ ca cao Tiền Giang giúp lấy đi lớp sừng già cỗi mà không rát da.', 'Việt Nam', 'Hạt cà phê Đắk Lắk xay nhuyễn, Bơ ca cao Tiền Giang, Dầu hoa rum', 'Làm sạch tế bào chết, cho làn da mặt mềm mịn, sáng bóng và đều màu.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (94, 15, 11, 'Mặt Nạ & Tẩy Da Chết Đường Đen Klairs Youthful Glow Sugar Mask', 'Mặt nạ đa năng 3 trong 1 tẩy da chết với tinh thể đường đen hữu cơ và bơ hạt mỡ làm mềm da.', 'Hàn Quốc', 'Đường đen hữu cơ, Bơ hạt mỡ, Dầu hạt jojoba, Dầu hạt bưởi', 'Tẩy sạch da chết nhẹ dịu, dưỡng ẩm và làm mềm các vùng da bong tróc sần sùi.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (95, 17, 11, 'Tẩy Tế Bào Chết Ngừa Mụn Eucerin Pro Acne Solution Scrub', 'Các vi hạt siêu nhỏ tác động nhẹ nhàng lên da kết hợp Acid Lactic làm thông thoáng chân lông.', 'Đức', 'Lactic Acid (AHA tự nhiên), Vi hạt Polyethylene siêu mịn', 'Giảm mụn đầu đen và mụn cám, không làm khô căng hay tổn thương da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (96, 5, 11, 'Mặt Nạ Tẩy Tế Bào Chết Tro Núi Lửa Innisfree Volcanic Calming Pore Clay Mask', 'Đá tro núi lửa Jeju kết hợp AHA/PHA làm sạch tế bào chết và bã nhờn dịu nhẹ mỗi ngày.', 'Hàn Quốc', 'Tro núi lửa Jeju Sphere, Phức hợp AHA/PHA, Nước khoáng có ga', 'Hút sạch bã nhờn dư thừa, làm dịu da nhạy cảm và se nhỏ chân lông.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (97, 8, 11, 'Mặt Nạ Đất Sét Tẩy Tế Bào Chết L''Oréal Paris Pure Clay Mask Illuminating', 'Kết hợp 3 loại đất sét khoáng tự nhiên từ núi lửa Pháp và chiết xuất sả làm sạch tế bào xỉn màu.', 'Pháp', 'Đất sét Kaolin, Đất sét Montmorillonite, Chiết xuất sả Yuzu', 'Thanh lọc tạp chất, làm sáng bừng làn da và tái tạo độ mềm mịn tức thì.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (98, 14, 11, 'Gel Tẩy Tế Bào Chết Cho Da Dầu Mụn Bioderma Sébium Gel Gommant', 'Hạt vi tẩy tế bào chết Polyethylene kết hợp Acid Glycolic và Salicylic tác động kép cơ học và hóa học.', 'Pháp', 'Fluidactiv, Axit Glycolic, Axit Salicylic, Vi hạt tròn', 'Làm sạch bã nhờn sâu trong chân lông, giảm bóng dầu và ngăn ngừa mụn cám.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (99, 16, 11, 'Tẩy Tế Bào Chết Dịu Nhẹ Simple Kind To Skin Smoothing Facial Scrub', 'Chiết xuất hạt gạo li ti tự nhiên kết hợp Pro-Vitamin B5 tẩy da chết dịu êm cho da nhạy cảm.', 'Anh', 'Hạt gạo xay mịn, Pro-Vitamin B5, Vitamin E', 'Loại bỏ nhẹ nhàng tế bào chết, trả lại làn da mịn mượt không hề châm chích.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (100, 18, 11, 'Kem Tẩy Tế Bào Chết Tái Tạo Bề Mặt Da Kiehl''s Epidermal Re-Texturizing Micro-Dermabrasion', 'Công nghệ siêu mài mòn vi mô với tinh thể vỏ sò tự nhiên kết hợp chiết xuất liễu trắng thảo mộc.', 'Mỹ', 'Bột vi tinh thể vỏ sò tự nhiên, Chiết xuất cây liễu trắng, Chiết xuất cúc La Mã', 'Làm phẳng bề mặt da thô ráp, làm mờ vết thâm và sẹo mụn nhẹ sau 1 lần dùng.', 1, 'ACTIVE', '2026-01-01 00:00:00');
INSERT INTO products (id, brand_id, category_id, name, description, origin, main_ingredients, benefits, is_featured, status, created_at) VALUES
    (101, 4, 11, 'Gel Tẩy Tế Bào Chết Chống Lão Hóa Paula''s Choice Skin Perfecting 8% AHA Gel', 'Chứa 8% Glycolic Acid (AHA) kết hợp chiết xuất hoa cúc và cúc vạn thọ làm sáng mịn da khô lão hóa.', 'Mỹ', '8% Glycolic Acid, Chiết xuất Cúc La Mã Chamomile, Lô hội', 'Đánh bay các vùng da khô sần sùi, làm mờ nếp nhăn li ti và kích thích sản sinh collagen.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (102, 1, 11, 'Dung Dịch Tẩy Da Chết Bí Đao Cocoon 2% BHA 140ml', 'BHA 2% tan trong dung môi tự nhiên chiết xuất bí đao giúp thẩm thấu sâu làm sạch mụn ẩn mụn đầu đen.', 'Việt Nam', '2% Salicylic Acid (BHA), Chiết xuất bí đao, Nước cất hoa hồng', 'Đẩy mụn ẩn, làm thông thoáng lỗ chân lông và hạn chế tiết bã nhờn.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (103, 12, 11, 'Mặt Nạ Tẩy Tế Bào Chết Đất Sét Khoáng Núi Lửa Vichy Purifying Clay Mask', 'Kết hợp 2 loại đất sét Kaolin và Bentonite cùng nước khoáng núi lửa hút sạch độc tố dưới da.', 'Pháp', 'Đất sét Kaolin, Bentonite, Nước khoáng Vichy, Tinh chất Lô Hội', 'Thu nhỏ lỗ chân lông, kiềm dầu thừa và đem lại làn da sáng mịn khỏe mạnh.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (104, 26, 11, 'Gel Tẩy Tế Bào Chết Sáng Mịn Da DHC Mineral Face Scrub', 'Hạt mơ thiên nhiên tự nhiên nghiền mịn kết hợp tro núi lửa làm sạch lớp sừng trên bề mặt da.', 'Nhật Bản', 'Hạt quả mơ nghiền mịn, Bùn khoáng biển sâu, Tinh dầu Oliu', 'Làm sáng da xỉn màu, kích thích tuần hoàn máu và đem lại vẻ bóng mượt.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (105, 19, 11, 'Gel Tẩy Tế Bào Chết Đông Y Dịu Nhẹ Sulwhasoo White Ginseng Radiance Mask', 'Chứa bột Bạch sâm tự nhiên quý hiếm giúp thanh lọc da chết trong khi tắm hoặc thư giãn.', 'Hàn Quốc', 'Bột Bạch sâm Hàn Quốc, Mật ong tự nhiên, Tinh chất thảo mộc Đông y', 'Thanh lọc độc tố, cấp ẩm sâu và nuôi dưỡng làn da sáng trong như ngọc bích.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (106, 9, 12, 'Mặt Nạ Ngủ Cấp Nước Chuyên Sâu Laneige Water Sleeping Mask EX', 'Công nghệ Sleeping Micro Biome kết hợp phức hợp Pro-biotics và Squalane thanh lọc da trong giấc ngủ.', 'Hàn Quốc', 'Sleeping Micro Biome, Pro-biotics Complex, Squalane thực vật', 'Phục hồi làn da rạng rỡ, căng mọng ngậm nước sau khi thức giấc vào sáng hôm sau.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (107, 18, 12, 'Mặt Nạ Đất Sét Hút Sạch Dầu Kiehl''s Rare Earth Deep Pore Cleansing Masque', 'Mặt nạ đất sét trắng Amazon huyền thoại của Kiehl''s hút sạch độc tố, bã nhờn và nhân mụn đầu đen.', 'Mỹ', 'Đất sét trắng vùng Amazon, Yến mạch nghiền, Chiết xuất Nha Đam', 'Thanh lọc lỗ chân lông, kiềm dầu đến 95% và se nhỏ chân lông tức thì.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (108, 5, 12, 'Mặt Nạ Đất Sét Tro Núi Lửa Innisfree Super Volcanic Pore Clay Mask 2X', 'Công nghệ hạt tro núi lửa Jeju 2X hút sạch gấp đôi lượng bã nhờn sâu trong lỗ chân lông.', 'Hàn Quốc', 'Tro núi lửa đảo Jeju 2X, Đất sét khoáng, Bột óc chó, AHA', 'Thu nhỏ lỗ chân lông, tẩy da chết nhẹ nhàng và làm mát dịu da tức thì.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (109, 1, 12, 'Mặt Nạ Bí Đao Cocoon Kháng Viêm & Giảm Mụn Mờ Thâm 100ml', 'Mặt nạ thuần chay kết hợp dịch chiết bí đao, rau má và tràm trà hút sạch dầu thừa trên da mụn.', 'Việt Nam', 'Chiết xuất bí đao, Tinh dầu tràm trà hữu cơ, Chiết xuất rau má, Đất sét Kaolin', 'Làm dịu vết mụn đỏ, kháng viêm và giảm tiết bã nhờn rõ rệt sau 20 phút.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (110, 15, 12, 'Mặt Nạ Giấy Làm Dịu Khẩn Cấp Klairs Midnight Blue Calming Sheet Mask', 'Mặt nạ giấy sợi tre chứa chiết xuất Guaiazulene chiết xuất từ hoa cúc La Mã màu xanh biển dịu mát.', 'Hàn Quốc', 'Guaiazulene hoa cúc, Chiết xuất Rau má Centella Asiatica, Bột than tre', 'Hạ nhiệt tức thì cho làn da bị cháy nắng hoặc kích ứng mẩn đỏ sau nặn mụn.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (111, 8, 12, 'Mặt Nạ Giấy Căng Mướt Da L''Oréal Paris Revitalift Crystal Micro-Essence Mask', 'Chứa lượng dưỡng chất tương đương 1 chai tinh chất Micro-Essence với công nghệ màng cotton siêu mỏng.', 'Pháp', 'Hoạt chất Salicylic Acid (BHA), Dưỡng chất Centella Asiatica', 'Thẩm thấu sâu gấp 10 lần, đem lại làn da sáng trong trẻo căng mọng tức thì.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (112, 14, 12, 'Mặt Nạ Cấp Ẩm Phục Hồi Khẩn Cấp Bioderma Sensibio Mask', 'Liệu pháp điều trị chuyên sâu cấp nước tức thì cho làn da nhạy cảm mất nước bị ngứa rát.', 'Pháp', 'Sáng chế Toléridine, Glycyrrhetinic Acid, Xylitol, Fructooligosaccharides', 'Hạ nhiệt cảm giác bốc hỏa, tăng cường ngưỡng chịu đựng sinh học của làn da.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (113, 12, 12, 'Mặt Nạ Ngủ Dưỡng Ẩm Chuyên Sâu Ban Đêm Vichy Aqualia Thermal Night Spa', 'Gel mặt nạ ngủ chứa nước khoáng Vichy và Hyaluronic Acid biến giấc ngủ thành liệu trình spa tại nhà.', 'Pháp', '15 Khoáng chất núi lửa Vichy, Hyaluronic Acid đa phân tử, Caffeine', 'Tái sinh làn da mệt mỏi, cấp nước suốt 48 giờ cho vẻ rạng rỡ căng tràn vào sáng hôm sau.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
