    (142, 8, 14, 'Kem Nền Mịn Nhẹ Thoáng Da L''Oréal Paris Infallible 24H Fresh Wear', 'Công nghệ hạt màu siêu mịn với mạng lưới bọt khí thoáng khí Oxygen Technology cho da thở thoải mái.', 'Pháp', 'Công nghệ bọt khí Oxygen, SPF 25, Vitamin E', 'Bền màu 24 giờ, chống trôi chống nước và mồ hôi trong điều kiện thời tiết nóng ẩm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (143, 5, 14, 'Phấn Nước Kiềm Dầu Mịn Màng Innisfree No-Sebum Mineral Cushion SPF35', 'Phấn nước kiềm dầu chiết xuất từ bột khoáng đảo Jeju và bạc hà cho lớp nền khô thoáng 48h.', 'Hàn Quốc', 'Bột khoáng No-Sebum tự nhiên, Chiết xuất Bạc Hà, Trà xanh', 'Kiềm dầu vượt trội, làm mờ lỗ chân lông và không bị lem dính vào khẩu trang.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (144, 23, 14, 'Phấn Nước Căng Mọng Tự Nhiên Rom&nd Nu Zero Cushion', 'Hạt phấn nano siêu nhỏ che phủ các khuyết điểm lồi lõm trên da đem lại làn da mịn màng như da mộc.', 'Hàn Quốc', 'Bột phấn siêu phân tử, Hyaluronic Acid, Niacinamide', 'Mỏng nhẹ tự nhiên không nặng mặt, che phủ lỗ chân lông và vết đỏ mụn hiệu quả.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (145, 24, 14, 'Phấn Nước Mỏng Nhẹ Tự Nhiên 3CE Bare Cover Cushion SPF50+', 'Công thức cushion tạo hiệu ứng làn da phủ sương trong veo chuẩn Hàn Quốc với độ chống nắng cao.', 'Hàn Quốc', 'Chiết xuất hạt quả bơ, Dầu jojoba, Bột khoáng bắt sáng', 'Bảo vệ da dưới nắng, tạo hiệu ứng căng mọng glowy tự nhiên.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (146, 19, 14, 'Phấn Nước Dưỡng Da Hoàn Hảo Sulwhasoo Perfecting Cushion SPF50+', 'Tuyệt tác cushion kết hợp tinh chất dưỡng da Đông y quý phái nuôi dưỡng làn da ẩm mịn căng sáng.', 'Hàn Quốc', 'Chiết xuất nấm Schizophyllum, Tinh chất Nhân sâm, Jaum Moisturizing', 'Che phủ nếp nhăn, tăng độ săn chắc và bảo vệ làn da tươi trẻ rạng rỡ suốt ngày dài.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (147, 12, 14, 'Kem Nền Che Khuyết Điểm Chuyên Nghiệp Vichy Dermablend 3D Correction', 'Công thức chuyên khoa da liễu chứa Acid Salicylic và Eperuline che phủ tuyệt đối sẹo lõm và mụn gồ ghề.', 'Pháp', 'Salicylic Acid (BHA), Eperuline, Bột màu khoáng tinh khiết', 'San phẳng bề mặt da mụn gồ ghề, che phủ 100% vết thâm đỏ và kiềm dầu 16 giờ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (148, 11, 14, 'Kem Lót Kiềm Dầu & Thu Nhỏ Chân Lông Maybelline Fit Me Matte + Poreless Primer', 'Kem lót kiềm dầu giúp làm mờ lỗ chân lông tức thì và giữ lớp nền bền đẹp không xê dịch suốt 16h.', 'Mỹ', 'Đất sét khoáng kiềm nhờn, Polyme làm mờ lỗ chân lông, SPF 20', 'Tạo lớp đệm mềm mịn như nhung, ngăn ngừa mồ hôi và bã nhờn làm chảy nền.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (149, 9, 14, 'Kem Lót Hiệu Chỉnh Sắc Tố Da Laneige Skin Veil Base SPF25', 'Kem lót màu tím và xanh ngọc giúp hiệu chỉnh các vùng da xỉn màu và vết ửng đỏ mụn tức thì.', 'Hàn Quốc', 'Bột khoáng ngọc trai phát sáng, Vitamin C, Chiết xuất quả mọng', 'Tạo nền da sáng trong veo đều màu chuẩn phong cách trang điểm K-Beauty.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (150, 20, 14, 'Phấn Nước Cao Cấp Sang Trọng Dior Forever Cushion Vỏ Da Cannage', 'Tuyệt tác cushion biểu tượng thời trang Paris với vỏ bọc da cannage tinh xảo và chất phấn lì nhung cao cấp.', 'Pháp', 'Chiết xuất Hoa Diên Vĩ, Bột khoáng phản chiếu ánh sáng, SPF 35', 'Che phủ hoàn hảo 24 giờ, mang lại đẳng cấp quý phái sang trọng cho phái đẹp.', 1, 'ACTIVE', '2026-01-01 00:00:00');
INSERT INTO products (id, brand_id, category_id, name, description, origin, main_ingredients, benefits, is_featured, status, created_at) VALUES
    (151, 10, 15, 'Phấn Má Hồng Mịn Nhẹ Ánh Nhũ MAC Mineralize Blush', 'Phấn má nung chứa các khoáng chất tinh khiết giúp gò má sáng bừng sức sống với sắc màu tinh tế.', 'Mỹ', 'Khoáng chất nung tinh khiết, Hạt nhũ ngọc trai siêu mịn', 'Tạo đôi gò má ửng hồng tươi tắn, bắt sáng tự nhiên tôn đường nét khuôn mặt.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (152, 5, 15, 'Phấn Phủ Bột Khoáng Kiềm Dầu Innisfree No-Sebum Mineral Powder', 'Hũ phấn phủ bột khoáng quốc dân hút sạch dầu thừa tức thì, cho làn da ráo mịn suốt cả ngày dài.', 'Hàn Quốc', 'Khoáng chất đảo Jeju tự nhiên, Tinh chất Bạc Hà hữu cơ', 'Kiềm dầu, giữ lớp trang điểm lâu trôi và dùng được cho cả da đầu kiềm dầu tóc bết.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (153, 24, 15, 'Phấn Má Hồng Mịn Màng Tươi Tắn 3CE Face Blush Mood Recipe', 'Chất phấn má siêu mịn bám chặt vào da suốt cả ngày không bị phai màu với tông màu đất thời thượng.', 'Hàn Quốc', 'Hạt bột màu micronized nén chặt, Tinh dầu hoa cúc', 'Tạo đôi má ửng hồng trong trẻo tự nhiên, không gây cảm giác dày phấn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (154, 11, 15, 'Phấn Phủ Dạng Nén Kiềm Dầu 16H Maybelline Fit Me Matte + Poreless Powder', 'Hạt phấn Perlite khoáng chất tự nhiên hấp thu bã nhờn mạnh mẽ, giữ lớp nền mờ lì suốt 16 giờ.', 'Mỹ', 'Khoáng chất Perlite núi lửa, Bột silica hút dầu, SPF 28', 'Kiềm dầu, che lỗ chân lông và làm đều màu da tự nhiên không bóng loáng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (155, 23, 15, 'Phấn Má Hồng Trái Cây Rom&nd Better Than Cheek', 'Hiệu ứng làm mờ lỗ chân lông Blur effect như vừa dùng filter, mang lại đôi má phơn phớt tự nhiên.', 'Hàn Quốc', 'Bột khoáng làm mờ, Chiết xuất việt quất và dâu tây', 'Màu má ửng ngọt ngào, chất phấn tan mịn không lộ vân da hay lỗ chân lông.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (156, 20, 15, 'Phấn Má Hồng Bắt Sáng Cao Cấp Dior Rosy Glow Blush', 'Phấn má hồng công nghệ Color Reviver phản ứng theo độ ẩm tự nhiên của da để tạo màu hồng riêng biệt.', 'Pháp', 'Hạt nhũ ngọc trai phát quang, Bột màu sắc tố vi mô', 'Đem lại đôi gò má ửng hồng tươi tắn tự nhiên bừng sáng sức sống suốt cả ngày.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (157, 21, 15, 'Phấn Má Hồng Sang Trọng Chanel Joues Contraste', 'Hộp phấn má tròn kinh điển của Chanel với hương thơm hoa hồng tinh tế và chất phấn nướng siêu mịn.', 'Pháp', 'Khoáng chất nướng siêu nhỏ, Chiết xuất tinh dầu hoa hồng quý', 'Tạo đường nét gò má thanh tú, sắc màu quý phái trường tồn theo năm tháng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (158, 10, 15, 'Phấn Phủ Bột Khoáng Cố Định Lớp Nền MAC Studio Fix Pro Set + Blur Weightless', 'Hạt phấn bột siêu tàng hình kiềm dầu suốt 8 giờ và khóa chặt lớp nền không xê dịch suốt ngày dài.', 'Mỹ', 'Bột khoáng quang học siêu vi, Dầu dưỡng nhẹ', 'Làm mờ lỗ chân lông tức thì, không gây đọng phấn rãnh cười hay hằn nếp nhăn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (159, 8, 15, 'Phấn Phủ Bột Kiềm Dầu Suốt 24 Giờ L''Oréal Paris Infallible Loose Setting Powder', 'Hạt phấn siêu nhẹ hấp thu bã nhờn dư thừa và giữ lớp trang điểm tươi mới suốt ngày hoạt động.', 'Pháp', 'Hạt phấn khoáng siêu vi, Bột Talc tinh khiết', 'Kiềm dầu, chống bóng nhờn và tạo bề mặt da láng mịn không tì vết.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (160, 1, 15, 'Phấn Phủ Bột Bí Đao Cocoon Kiềm Dầu Kháng Khuẩn 10g', 'Phấn phủ bột khoáng thuần chay kết hợp chiết xuất bí đao và tràm trà bảo vệ da dầu mụn.', 'Việt Nam', 'Chiết xuất bí đao, Tinh dầu tràm trà, Bột bắp tự nhiên, Bột ngọc trai nhẹ', 'Hút sạch dầu bóng nhờn, kháng khuẩn cho các nốt mụn và giữ da thoáng nhẹ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (161, 24, 15, 'Bột Phấn Phủ Bắt Sáng Tạo Khối 3CE Strobing Skin Powder', 'Hạt nhũ ngọc trai siêu mịn bắt sáng lấp lánh ở các điểm cao trên khuôn mặt như sống mũi và gò má.', 'Hàn Quốc', 'Bột nhũ khoáng ngọc trai phát quang, Vitamin E', 'Tạo hiệu ứng gương mặt thanh thoát thon gọn và căng tràn sức sống dưới ánh đèn.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (162, 23, 15, 'Phấn Bắt Sáng Căng Bóng Ngọc Trai Rom&nd See-Through Veillighter', 'Hạt phấn nhũ mịn màng tạo độ óng ả trong veo tựa làn nước mùa thu trên đôi gò má.', 'Hàn Quốc', 'Bột ngọc trai siêu phân tử, Tinh dầu dừa dưỡng ẩm', 'Bắt sáng tự nhiên không lộ hạt nhũ thô, giữ vẻ tươi tắn suốt cả ngày.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (163, 11, 15, 'Má Hồng Kem Dạng Thỏi Maybelline Cheek Heat Gel-Cream Blush', 'Chất gel cream mỏng nhẹ gốc nước tan tiệp vào da cho đôi má ửng màu tự nhiên như không trang điểm.', 'Mỹ', 'Nước khoáng tự nhiên, Sắc tố màu dạng gel tan chảy', 'Dễ tán bằng tay, dưỡng ẩm nhẹ cho gò má căng mướt tươi tắn.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (164, 9, 15, 'Phấn Phủ Bột Cấp Nước Khóa Ẩm Laneige Neo Essential Blurring Finish Powder', 'Hạt phấn bột chứa tinh chất Hyaluronic Acid dạng nén khóa chặt độ ẩm trong khi kiểm soát bã nhờn bên ngoài.', 'Hàn Quốc', 'Micro Hyaluronic Acid, Men nấm men xanh, Bột silica kiềm dầu', 'Làm mịn màng lỗ chân lông, kiềm dầu mà không làm mốc khô da vùng mũi má.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (165, 10, 15, 'Phấn Bắt Sáng Thần Thánh MAC Mineralize Skinfinish Extra Dimension', 'Tuyệt tác phấn bắt sáng nung chứa khoáng chất quý hiếm cho làn da phát sáng rạng ngời dưới mọi góc chụp.', 'Mỹ', 'Bột khoáng nướng ngọc trai 77 phức hợp, Vitamin E', 'Tạo hiệu ứng gương mặt thanh tú nổi bật, bền màu suốt 10 giờ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (166, 11, 16, 'Chuốt Mi Dài & Dày Mi Chống Trôi Maybelline Hypercurl Waterproof Mascara', 'Mascara huyền thoại giữ nếp mi cong vút và dày gấp 3 lần suốt 36 giờ bất chấp thời tiết nóng ẩm.', 'Mỹ', 'Sáp tự nhiên, Hợp chất Polymer định hình mi, Gel dưỡng mi', 'Giúp hàng mi cong vút tự nhiên, chống lem chống trôi kháng nước tuyệt đối.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (167, 11, 16, 'Mascara Dài & Cong Mi Bất Tận Maybelline Lash Sensational Sky High Waterproof', 'Cây chuốt mi gây sốt toàn cầu với đầu cọ Flex Tower linh hoạt chạm tới từng sợi mi ngắn nhất.', 'Mỹ', 'Chiết xuất tre tự nhiên, Sợi tơ kéo dài mi Pro-Keratin', 'Kéo dài mi vô tận từ gốc tới ngọn, không gây vón cục hay nặng mi.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (168, 24, 16, 'Bảng Phấn Mắt 9 Ô Thời Thượng 3CE Multi Eye Color Palette', 'Bảng màu mắt tông nâu cam đất thời thượng với 9 ô màu từ lì mịn mượt đến nhũ lấp lánh.', 'Hàn Quốc', 'Bột khoáng màu cao cấp, Hạt nhũ ngọc trai bắt sáng', 'Dễ phối màu từ trang điểm tự nhiên đi học đến quyến rũ dự tiệc ban đêm.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (169, 23, 16, 'Bảng Phấn Mắt 4 Ô Ngọt Ngào Rom&nd Better Than Eyes', 'Bảng phấn mắt nhỏ gọn tiện lợi gồm 3 ô lì mịn màng và 1 ô nhũ kim tuyến lấp lánh như giọt sương.', 'Hàn Quốc', 'Hạt bột màu siêu mịn kiểm soát dầu mí mắt, Nhũ ngọc trai', 'Chất phấn không bay bụi, bám chặt vào mí mắt suốt cả ngày.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (170, 11, 16, 'Bút Kẻ Mắt Nước Nét Mảnh Siêu Lì Maybelline Hyper Sharp Liner Extreme', 'Đầu cọ vi sợi 0.01mm siêu sắc mảnh lướt êm ái trên mí mắt cho đường kẻ mắt mèo chuẩn xác từng milimet.', 'Mỹ', 'Polyme màng phim khóa màu, Mực carbon đen tuyền', 'Kháng nước, kháng mồ hôi, không lem trôi suốt 36 giờ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (171, 8, 16, 'Chuốt Mi Dày Mi Dài Mi Quyến Rũ L''Oréal Paris Voluminous Lash Paradise', 'Đầu cọ lượn sóng hơn 200 sợi lông mềm mại ôm sát sợi mi cho hàng mi dày gấp 20 lần mềm mại như lông vũ.', 'Pháp', 'Dầu thầu dầu castor oil nuôi mi, Sáp hoa hồng, Sợi vi dệt', 'Làm mi dày rậm quyến rũ mà không hề vón cục hay làm rụng mi.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (172, 20, 16, 'Mascara Cao Cấp Dài & Cong Mi Dior Diorshow Mascara 24H', 'Mascara sàn diễn thời trang danh giá với công nghệ sợi vi lụa tơ tằm đem lại ánh nhìn hút hồn sâu thẳm.', 'Pháp', 'Chiết xuất Hoa Ngô Dại làm dịu mắt, Sợi tơ tằm nguyên chất', 'Định hình hàng mi cong vút chuẩn sắc Haute Couture suốt 24 giờ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (173, 5, 16, 'Mascara Cong Mi Tự Nhiên Thuần Chay Innisfree Simple Label Long & Curl', 'Chuốt mi thuần chay đạt chứng nhận EVE VEGAN lành tính tuyệt đối cho mắt nhạy cảm và người đeo lens.', 'Hàn Quốc', 'Chiết xuất rễ cây hoa cẩm tú cầu Jeju, Sáp thực vật', 'Giữ nếp mi cong vút tự nhiên, nhẹ tênh không cay mắt.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (174, 10, 16, 'Nhũ Mắt Dạng Lỏng Lấp Lánh MAC Dazzleshadow Liquid', 'Nhũ mắt dạng lỏng tan nhẹ lướt êm với hàng triệu hạt tinh thể bắt sáng lấp lánh như bầu trời đêm đầy sao.', 'Mỹ', 'Hạt nhũ đa chiều siêu sáng, Gel gốc nước bám dính cao', 'Khô nhanh, không lem rơi rụng hạt nhũ xuống má suốt buổi tiệc.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (175, 11, 16, 'Chì Kẻ Mày Định Hình Tự Nhiên Maybelline Define & Blend Brow Pencil', 'Thiết kế đầu chì vát xéo tiện lợi kết hợp đầu chổi xoắn chải mày giúp tạo dáng chân mày tự nhiên.', 'Mỹ', 'Sáp tự nhiên mềm mại, Bột màu khoáng tiệp tone da', 'Lên màu chuẩn, không vón cục, chống nước không sợ trôi màu đuôi mày.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (176, 24, 16, 'Bút Kẻ Mắt Dạ Nét Mảnh Chống Nước 3CE Super Slim Pen Eyeliner', 'Đầu bút lông dạ mềm mại linh hoạt tạo đường kẻ mắt từ tự nhiên thanh thoát đến mắt mèo sắc lẹm.', 'Hàn Quốc', 'Polyme tạo màng chống thấm nước, Sắc tố mực đen', 'Không lem khi đổ mồ hôi hay gặp nước mưa, tẩy trang dễ dàng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (177, 23, 16, 'Mascara Định Hình Cong Mi Tự Nhiên Rom&nd Han All Fix Mascara', 'Đầu cọ thon nhỏ len lỏi chải tơi từng sợi mi không vón cục, tạo hiệu ứng mi dài thanh thoát.', 'Hàn Quốc', 'Sợi nối mi vi mô, Sáp định hình mi cong', 'Cố định hàng mi cong vút suốt ngày dài kể cả với người có mí mắt dầu sụp mí.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (178, 5, 16, 'Chì Kẻ Mày 2 Đầu Tiện Lợi Innisfree Auto Eyebrow Pencil', 'Cây chì kẻ mày đầu oval dẹp thần thánh giúp viền khung và phẩy sợi chân mày siêu dễ dàng.', 'Hàn Quốc', 'Bột khoáng thiên nhiên, Chiết xuất đậu nành nuôi dưỡng chân mày', 'Dáng mày vào nếp tự nhiên sắc nét, không bị bết dính sợi lông mày.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (179, 8, 16, 'Phấn Mắt Nhũ Mịn Đơn Sắc L''Oréal Paris Color Queen Oil Eyeshadow', 'Công thức phấn mắt dạng kem dầu ép mịn đậm đặc sắc tố lấp lánh lên màu chuẩn chỉ với 1 ngón tay.', 'Pháp', 'Dầu dưỡng thực vật, Bột màu sắc tố ngọc trai', 'Chất phấn mượt mà như bơ, không bay bụi phấn vào mắt.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (180, 21, 16, 'Bảng Phấn Mắt 4 Màu Đẳng Cấp Chanel Les 4 Ombres Multi-Effect', 'Bảng phấn mắt 4 ô kinh điển của Chanel với công thức nướng đem lại lớp màu mượt mà sâu thẳm.', 'Pháp', 'Khoáng chất micronized nung tinh khiết, Bột ngọc trai', 'Tạo chiều sâu huyền bí cho đôi mắt, lưu giữ sắc màu quý phái cả ngày.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (181, 1, 17, 'Tẩy Tế Bào Chết Cơ Thể Cà Phê Đắk Lắk Cocoon Dak Lak Coffee Body Polish', 'Tẩy tế bào chết cơ thể thuần chay thơm lừng hương cà phê Việt Nam, đánh bay viêm lỗ chân lông và thâm sần.', 'Việt Nam', 'Hạt cà phê Đắk Lắk xay nhuyễn, Bơ ca cao Tiền Giang, Dầu dừa Bến Tre', 'Loại bỏ lớp sừng già cỗi, làm đều màu da và nuôi dưỡng làn da body mềm mịn như nhung.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (182, 29, 17, 'Tẩy Tế Bào Chết Toàn Thân Bath & Body Works Aromatherapy Eucalyptus Spearmint', 'Muối biển tự nhiên kết hợp tinh dầu khuynh diệp và bạc hà giải tỏa căng thẳng stress mệt mỏi.', 'Mỹ', 'Muối biển khoáng, Tinh dầu khuynh diệp, Tinh dầu bạc hà, Dầu hạt hướng dương', 'Làm mịn các vùng da thô ráp cùi chỏ đầu gối, lưu lại hương thơm thư giãn như spa.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (183, 6, 17, 'Kem Dưỡng Tẩy Da Chết Cơ Thể CeraVe SA Smoothing Cream 10% Urea & Salicylic', 'Công thức chứa 10% Urea, Axit Salicylic và 3 Ceramide thiết yếu làm mịn làn da sần sùi viêm nang lông.', 'Mỹ', '10% Urea, Salicylic Acid (BHA), 3 Ceramide thiết yếu, LHA', 'Tẩy sạch da chết sần sùi viêm lỗ chân lông, làm mềm vùng da khô ráp cánh tay bắp chân.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (184, 4, 17, 'Kem Dưỡng Thể Tẩy Tế Bào Chết Paula''s Choice Weightless Body Treatment 2% BHA', 'Sản phẩm điều trị viêm nang lông và mụn lưng nổi tiếng của Paula''s Choice với 2% BHA dạng kem dưỡng.', 'Mỹ', '2% Salicylic Acid (BHA), Chiết xuất Trà xanh, Vitamin E, Bisabolol', 'Giải quyết dứt điểm mụn lưng, mụn ngực và viêm nang lông, trả lại làn da mịn màng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (185, 1, 17, 'Tẩy Da Chết Body Hoa Hồng Cocoon Làm Sáng Mịn Da 200ml', 'Cánh hoa hồng tươi Hậu Giang kết hợp hạt cà phê nghiền mịn và dầu jojoba hữu cơ.', 'Việt Nam', 'Cánh hoa hồng tươi, Hạt cà phê xay mịn, Dầu jojoba, Vitamin B5', 'Làm sáng da thâm sạm nách bẹn mông, lưu lại làn da ngát hương hoa hồng quyến rũ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (186, 28, 17, 'Muối Tẩy Tế Bào Chết & Làm Sáng Body Tsubaki Camellia Scrub', 'Muối biển Nhật Bản giàu khoáng chất kết hợp tinh dầu hoa trà đỏ Tsubaki nuôi dưỡng da mượt mà.', 'Nhật Bản', 'Muối khoáng biển Seto, Dầu hoa trà đỏ Tsubaki, Sữa ong chúa', 'Làm sạch sừng già cỗi, cấp ẩm bóng mượt và ngăn ngừa lão hóa da cơ thể.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (187, 29, 17, 'Tẩy Tế Bào Chết Hương Nước Hoa Bath & Body Works Into The Night Body Scrub', 'Đường hạt mịn tự nhiên hòa quyện tinh chất bơ hạt mỡ và hương thơm dạ tiệc sang trọng quyến rũ.', 'Mỹ', 'Hạt đường mía tự nhiên, Bơ hạt mỡ hữu cơ, Dầu dừa, Vitamin E', 'Làm mịn da tức thì, để lại hương thơm nồng nàn lưu luyến suốt 6 giờ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (188, 30, 17, 'Tẩy Tế Bào Chết Body Victoria''s Secret Pure Seduction Smoothing Scrub', 'Hạt đường tinh thể nhuyễn mịn kết hợp quả mận ép và hoa lan Nam Phi tạo nên mùi hương ngọt ngào.', 'Mỹ', 'Đường mía tinh luyện, Chiết xuất mận đỏ ép, Tinh dầu hoa lan', 'Tẩy da chết êm ái, mang lại làn da body mềm mượt như lụa satin.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (189, 5, 17, 'Tẩy Tế Bào Chết Body Trà Xanh Innisfree Green Tea Pure Body Gel Scrub', 'Hạt óc chó xay nhuyễn trong gel tạo bọt trà xanh hữu cơ vừa tắm vừa tẩy tế bào chết 2 trong 1.', 'Hàn Quốc', 'Bột vỏ quả óc chó, Chiết xuất trà xanh Jeju Beauty Green Tea', 'Làm sạch tế bào chết dịu nhẹ, đem lại cảm giác mát mẻ sảng khoái sau khi tắm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (190, 8, 17, 'Sữa Dưỡng Thể Tẩy Tế Bào Chết Sáng Da L''Oréal Paris Glycolic-Bright Body Lotion', 'Chứa 1% Glycolic Acid (AHA) và Niacinamide dưỡng sáng da toàn thân và mờ vết thâm sạm.', 'Pháp', '1% Glycolic Acid, Niacinamide, Bơ hạt mỡ, Vitamin C', 'Làm sáng các vùng da xỉn màu khuỷu tay đầu gối, nuôi dưỡng da căng mịn ẩm mượt.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (191, 14, 17, 'Kem Tẩy Da Chết Toàn Thân Cho Da Khô Nhạy Cảm Bioderma Atoderm Gel Douche Gommante', 'Công thức vi hạt tròn không gây trầy xước kết hợp phức hợp dưỡng ẩm Skin Protect Complex.', 'Pháp', 'Skin Protect Complex, Vi hạt tròn Polyethylene, Niacinamide', 'Tẩy da chết êm dịu, bảo vệ độ ẩm tự nhiên cho làn da khô nhạy cảm dễ kích ứng.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (192, 18, 17, 'Tẩy Tế Bào Chết Body Bưởi Chùm Kiehl''s Gently Exfoliating Body Scrub Grapefruit', 'Hạt tẩy tế bào chết từ vỏ quả mơ và hoa cúc La Mã đánh thức làn da với hương bưởi chùm tươi mát.', 'Mỹ', 'Hạt mơ tự nhiên nghiền mịn, Chiết xuất Bưởi chùm, Nha đam', 'Tẩy da chết toàn thân, giúp da mềm mại và lưu hương cam chanh sảng khoái.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (193, 26, 17, 'Muối Tắm Tẩy Tế Bào Chết Khoáng Biển DHC Mineral Body Scrub', 'Muối biển sâu Brittany Pháp giàu nguyên tố vi lượng kết hợp dầu olive và tinh chất bạc hà.', 'Nhật Bản', 'Muối biển vùng Brittany Pháp, Tinh dầu Olive hữu cơ, Tinh dầu Bạc hà', 'Thanh lọc độc tố, giảm tình trạng tích nước và đem lại cảm giác nhẹ nhõm thư thái.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (194, 17, 17, 'Sữa Dưỡng Thể Cấp Ẩm Chuyên Sâu 10% Urea Eucerin Complete Repair Moisture Lotion', 'Chứa 10% Urea kết hợp Ceramide và Gluco-Glycerol phục hồi chuyên sâu làn da khô nứt vảy cá.', 'Đức', '10% Urea, Ceramide-3, Gluco-Glycerol tự nhiên', 'Làm mềm các mảng sừng dày cộm ráp ngứa, duy trì độ ẩm suốt 48 giờ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (195, 27, 17, 'Tẩy Tế Bào Chết Cơ Thể Tinh Dầu Argan Moroccanoil Body Polishing Scrub', 'Bột vỏ hạt argan nghiền mịn kết hợp tinh dầu argan nguyên chất nuôi dưỡng làn da bóng mượt quý phái.', 'Israel', 'Bột vỏ hạt Argan, Tinh dầu Argan hữu cơ, Dầu quả bơ, Dầu hoa anh thảo', 'Đánh bay da chết sần sùi, để lại hương thơm hổ phách trứ danh của Moroccanoil.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (196, 1, 18, 'Nước Dưỡng Tóc Tinh Dầu Bưởi Cocoon Pomelo Hair Tonic', 'Giải pháp thuần chay giải cứu mái tóc yếu gãy rụng với tinh dầu vỏ bưởi nguyên chất và Xylishine.', 'Việt Nam', 'Tinh dầu bưởi nguyên chất, Xylishine, Vitamin B5, Baicapil', 'Giảm gãy rụng rõ rệt, kích thích mọc tóc con và nuôi dưỡng nang tóc chắc khỏe bồng bềnh.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (197, 1, 18, 'Dầu Gội Bưởi Không Sulfate Giảm Rụng Tóc Cocoon Pomelo Shampoo', 'Dầu gội thuần chay không chứa chất tẩy rửa sulfate mạnh, dịu nhẹ cho da đầu nhạy cảm và tóc hư tổn.', 'Việt Nam', 'Tinh dầu vỏ bưởi nguyên chất, Xylishine, Vitamin B5', 'Làm sạch dịu nhẹ tóc và da đầu, giảm rụng tóc và nuôi dưỡng tóc bồng bềnh chắc khỏe.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (198, 28, 18, 'Dầu Gội Dưỡng Tóc Chuẩn Salon Nhật Bản Tsubaki Premium Moist & Repair Shampoo', 'Công nghệ thẩm thấu CMC mở rộng đường dẫn dưỡng chất vào sâu lõi tóc phục hồi hư tổn tức thì.', 'Nhật Bản', 'Dầu hoa trà đỏ Tsubaki, Sữa ong chúa, Protein đậu nành', 'Cho mái tóc suôn mềm óng ả chuẩn salon Nhật Bản, giải cứu tóc khô xơ chẻ ngọn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (199, 27, 18, 'Tinh Dầu Dưỡng Tóc Thần Thánh Moroccanoil Treatment Original', 'Tinh dầu dưỡng tóc số 1 thế giới chiết xuất từ dầu argan giàu chất chống oxy hóa và vitamin E.', 'Israel', 'Dầu Argan nguyên chất hữu cơ, Chiết xuất hạt lanh Linseed, Vitamin E', 'Biến đổi mái tóc xơ rối thành suôn mượt bóng bẩy ngay giọt đầu tiên, rút ngắn thời gian sấy tóc.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (200, 8, 18, 'Dầu Gội Phục Hồi Tóc Hư Tổn Toàn Diện L''Oréal Paris Elseve Total Repair 5', 'Chứa hoạt chất Cement Ceramide mô phỏng chất xi măng tự nhiên hàn gắn 5 dấu hiệu tóc hư tổn.', 'Pháp', 'Cement Ceramide mô phỏng sinh học, Protein lúa mì thủy phân', 'Chấm dứt 5 dấu hiệu: gãy rụng, khô ráp, xơ yếu, chẻ ngọn và mất độ bóng.', 0, 'ACTIVE', '2026-01-01 00:00:00');
INSERT INTO products (id, brand_id, category_id, name, description, origin, main_ingredients, benefits, is_featured, status, created_at) VALUES
    (201, 8, 18, 'Dầu Dưỡng Tóc Cao Cấp L''Oréal Paris Elseve Extraordinary Oil Chiết Xuất 6 Loài Hoa', 'Chiết xuất từ 6 loài hoa quý hiếm nuôi dưỡng mái tóc mềm mại óng ả bồng bềnh không bết dính.', 'Pháp', 'Tinh dầu 6 loài hoa quý (Hoa sen, Cúc, Tiara, Hồng, Lanh, Thược dược)', 'Dưỡng ẩm sâu, bảo vệ tóc trước nhiệt độ máy sấy đến 230 độ C.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (202, 28, 18, 'Mặt Nạ Tóc Phục Hồi Cao Cấp Tsubaki Premium EX Repair Mask', 'Mặt nạ tóc xả ngay không cần ủ với công nghệ định vị hư tổn phục hồi sợi tóc bóng như tơ lụa.', 'Nhật Bản', 'Dầu hoa trà đỏ Tsubaki lên men, Axit Amin thẩm thấu, Squalane', 'Phục hồi tóc cháy tẩy nhuộm ngay lập tức, tiết kiệm thời gian ủ tóc.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (203, 5, 18, 'Dầu Dưỡng Tóc Hoa Trà Phục Hồi Innisfree Camellia Essential Hair Oil Serum', 'Tinh dầu hoa trà đảo Jeju thẩm thấu nhanh vào các lớp biểu bì tóc bị chẻ ngọn do uốn nhuộm.', 'Hàn Quốc', 'Dầu hoa trà đảo Jeju lên men, Ceramide bảo vệ tóc', 'Làm mượt tức thì các lọn tóc rối xơ xác, giữ nếp uốn sóng tự nhiên bồng bềnh.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (204, 1, 18, 'Dầu Xả Bưởi Phục Hồi & Giảm Gãy Rụng Cocoon Pomelo Conditioner', 'Dầu xả thuần chay không chứa silicon giúp làm mềm mượt sợi tóc mà không làm bẹp dính chân tóc.', 'Việt Nam', 'Tinh dầu vỏ bưởi, Vitamin B5, Chiết xuất rễ cây phỉ, Xylishine', 'Gỡ rối nhẹ nhàng, giảm rụng tóc khi chải và mang lại mái tóc suôn mượt ngát hương bưởi.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (205, 26, 18, 'Tinh Chất Kích Thích Mọc Tóc Chuyên Sâu DHC Hair Growth Tonic', 'Dược liệu cổ truyền Nhật Bản kết hợp tinh dầu bạc hà kích thích vi tuần hoàn máu nuôi nang tóc.', 'Nhật Bản', 'Chiết xuất rễ Hoàng Cầm, Nhân sâm Panax, Tinh dầu Bạc hà', 'Kích thích tóc con mọc dày dài, ngăn ngừa rụng tóc từng mảng và hói đầu sớm.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (206, 18, 18, 'Dầu Gội Dưỡng Ẩm Axit Amin Kiehl''s Amino Acid Shampoo', 'Công thức tạo bọt kem béo ngậy giàu axit amin và dầu dừa tinh khiết làm sạch dịu nhẹ da đầu.', 'Mỹ', 'Phức hợp Axit Amin, Dầu dừa nguyên chất, Protein hạt lúa mì', 'Tạo độ phồng tự nhiên cho tóc mỏng xẹp, duy trì độ ẩm mềm mại cả ngày.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (207, 27, 18, 'Dầu Gội Phục Hồi Độ Ẩm Moroccanoil Moisture Repair Shampoo', 'Dầu gội phục hồi cao cấp chứa dầu argan và keratin tăng cường liên kết tóc bị đứt gãy do hóa chất.', 'Israel', 'Dầu Argan hữu cơ, Keratin tái cấu trúc, Axit béo thiết yếu', 'Khôi phục độ đàn hồi cho mái tóc tẩy nhuộm, không chứa sulfat và paraben.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (208, 28, 18, 'Dầu Gội Phục Hồi Chống Gãy Rụng Tsubaki Premium Volume & Repair', 'Công nghệ nâng phồng chân tóc kết hợp dầu hoa trà lên men cho mái tóc bồng bềnh dồi dào sức sống.', 'Nhật Bản', 'Dầu hoa trà vàng Tsubaki, Tinh dầu hương thảo, Axit Citric', 'Tăng độ bồng bềnh cho mái tóc bết dính xẹp lép, ngăn ngừa rụng tóc.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (209, 1, 18, 'Serum Sa-chi Phục Hồi Tóc Hư Tổn Cocoon Inca Inchi Hair Serum 70ml', 'Dầu hạt sa-chi giàu Omega 3-6-9 đậm đặc gấp 40 lần dầu Argan bao bọc lớp biểu bì sợi tóc.', 'Việt Nam', 'Dầu hạt Sa-chi Đắk Lắk, Vitamin E, Tinh dầu hương thảo', 'Hàn gắn ngọn tóc chẻ ngọn, bảo vệ tóc trước tia UV và nhiệt độ cao.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (210, 8, 18, 'Kem Ủ Tóc Phục Hồi Toàn Diện L''Oréal Paris Elseve Total Repair 5 Deep Repairing Mask', 'Kem ủ đậm đặc chứa Micro-Ceramide thẩm thấu sâu nuôi dưỡng tóc bóng mượt chỉ sau 3 phút.', 'Pháp', 'Micro-Ceramide, Protein lúa mì, Axit Amin tái sinh', 'Giải cứu mái tóc khô xơ cháy nắng, trả lại vẻ suôn mượt óng ả.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (211, 13, 19, 'Nước Hoa Nữ Cao Cấp LUNEA Midnight Rose Eau De Parfum', 'Tuyệt tác hương thơm mang phong cách Paris hoa lệ với nốt hương hoa hồng huyền bí hòa quyện cùng xạ hương ấm áp.', 'Pháp', 'Hoa hồng Damask, Quả mọng đen, Gỗ tuyết tùng, Xạ hương trắng', 'Lưu hương quyến rũ nồng nàn từ 8 đến 12 giờ, tỏa hương tinh tế quý phái trong bán kính 2 mét.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (212, 21, 19, 'Nước Hoa Nữ Biểu Tượng Chanel Coco Mademoiselle Eau De Parfum', 'Biểu tượng nước hoa nữ vĩ đại nhất mọi thời đại mở đầu với hương cam tươi mát và bừng nở cùng hoa hồng Thổ Nhĩ Kỳ.', 'Pháp', 'Cam Bergamot, Hoa hồng Thổ Nhĩ Kỳ, Hoắc hương Patchouli, Vani Bourbon', 'Lưu hương đỉnh cao hơn 12 giờ, toát lên phong thái tiểu thư Paris độc lập kiêu kỳ.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (213, 20, 19, 'Nước Hoa Nam Lịch Lãm Phong Trần Dior Sauvage Eau De Parfum', 'Tuyệt tác nước hoa nam bán chạy số 1 hành tinh với hương cam Bergamot vùng Calabria và hổ phách Ambroxan ma mị.', 'Pháp', 'Cam Bergamot Calabria, Tiêu Tứ Xuyên, Hương hoa Oải hương, Ambroxan', 'Tỏa hương lôi cuốn mãnh liệt, khẳng định bản lĩnh phái mạnh phong trần nam tính.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (214, 22, 19, 'Nước Hoa Nữ Quyến Rũ Gây Nghiện YSL Black Opium Eau De Parfum', 'Sự hòa quyện bùng nổ giữa cà phê đen kích thích và hoa trắng ngọt ngào tạo nên nét quyến rũ mê hoặc.', 'Pháp', 'Cà phê đen nguyên chất, Hoa nhài trắng Sambac, Vani phương Đông, Gỗ tuyết tùng', 'Lưu hương 8-10 giờ, tôn vinh hình ảnh người phụ nữ cá tính hiện đại gợi cảm.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (215, 20, 19, 'Nước Hoa Nữ Tiểu Thư Ngọt Ngào Miss Dior Eau De Parfum', 'Bó hoa hồng Grasse rực rỡ sắc màu được thắt nơ Haute Couture tinh xảo mang lại nét nữ tính đài các.', 'Pháp', 'Hoa hồng xứ Grasse, Hoa chuông thung lũng, Hoa diên vĩ, Gỗ đàn hương', 'Mùi hương ngập tràn tình yêu và sự lãng mạn, lưu hương bền bỉ suốt cả ngày.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (216, 21, 19, 'Nước Hoa Nam Nam Tính Quyền Lực Bleu De Chanel Eau De Parfum', 'Hương thơm gỗ thơm nồng ấm kết hợp bưởi tươi và tuyết tùng tôn vinh sự tự do của quý ông thành đạt.', 'Pháp', 'Quả bưởi hồng, Tinh dầu Bạc hà, Hương gỗ Tuyết tùng, Hương Nhang trầm hương', 'Độ bám tỏa hương cực đỉnh, hoàn hảo cho môi trường công sở lịch lãm và dạ tiệc sang trọng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (217, 22, 19, 'Nước Hoa Nữ Nồng Nàn Kiêu Hãnh YSL Libre Eau De Parfum', 'Bản tuyên ngôn tự do hòa quyện giữa hoa oải hương nước Pháp và hoa cam Maroc rực rỡ gợi cảm.', 'Pháp', 'Hoa oải hương Provence Pháp, Hoa cam Maroc, Xạ hương quý, Vani Madagascar', 'Lưu hương 10-12 giờ, phong cách sang chảnh kiêu sa đầy khí chất.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (218, 13, 19, 'Nước Hoa Nữ Nắng Hè Nhiệt Đới Estée Lauder Bronze Goddess Eau De Parfum', 'Hương thơm quyến rũ ấm áp của dừa nướng, hoa tiare và vani gợi nhớ về kỳ nghỉ biển ngập tràn nắng vàng.', 'Mỹ', 'Quả dừa tươi, Hoa Tiare Tahiti, Hổ phách ấm, Vani ngọt ngào', 'Mùi hương gợi cảm thư thái, lý tưởng cho những ngày hè rực rỡ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (219, 21, 19, 'Nước Hoa Nữ Ngọt Ngào Thanh Khiết Chanel Chance Eau Tendre EDP', 'Hương thơm hoa quả dịu dàng lãng mạn với bưởi thanh khiết, mộc qua và hoa nhài trắng e ấp.', 'Pháp', 'Quả bưởi, Trái mộc qua, Hoa nhài Sambac, Xạ hương trắng tinh khôi', 'Lưu hương nhẹ nhàng thanh lịch, tôn lên nét trong sáng đáng yêu của phái đẹp.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (220, 22, 19, 'Nước Hoa Nam Tươi Mát Bản Lĩnh YSL Y Eau De Parfum', 'Nốt hương mở đầu từ táo xanh giòn tan và cam bergamot kết hợp gỗ tuyết tùng nam tính hiện đại.', 'Pháp', 'Táo xanh tươi mát, Cây xô thơm Sage, Gỗ tuyết tùng, Đậu Tonka', 'Mùi hương nam đa dụng số 1 có thể dùng quanh năm từ đi làm đến hẹn hò.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (221, 20, 19, 'Nước Hoa Nữ Nữ Tính Rạng Ngời Dior J''adore Eau De Parfum', 'Bó hoa vàng kim quý tộc hội tụ hoa ngọc lan tây Ylang-Ylang Comoros và hoa nhài Grasse tráng lệ.', 'Pháp', 'Hoa ngọc lan tây Ylang-Ylang, Hoa hồng Damask, Hoa nhài Sambac', 'Biểu tượng của sự quyền quý xa hoa, tỏa hương thanh cao ngút ngàn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (222, 13, 19, 'Nước Hoa Nữ Lãng Mạn Tinh Khôi Estée Lauder Beautiful Magnolia EDP', 'Hương hoa mộc lan tinh khôi hòa cùng hoa sen nước và gỗ tuyết tùng tạo nên câu chuyện tình say đắm.', 'Mỹ', 'Cánh hoa mộc lan Magnolia, Hoa sen nước, Xạ hương ấm áp', 'Hương thơm dịu dàng trong trẻo như làn gió mùa xuân mơn man.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (223, 21, 19, 'Nước Hoa Huyền Thoại Thế Giới Chanel No.5 Eau De Parfum', 'Chai nước hoa huyền thoại hơn 100 năm tuổi với phức hợp Aldehydes hoa cỏ sang trọng bất hủ.', 'Pháp', 'Phức hợp Aldehydes, Hoa hồng tháng Năm xứ Grasse, Hoa nhài, Gỗ đàn hương', 'Mùi hương kinh điển vĩnh cửu định hình chuẩn mực quý bà thượng lưu.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (224, 22, 19, 'Nước Hoa Nữ Quyến Rũ Paris YSL Mon Paris Eau De Parfum', 'Hương thơm tình yêu mãnh liệt thắp sáng tháp Eiffel với dâu tây mọng đỏ và hoa cà độc dược Datura.', 'Pháp', 'Dâu tây, Quả mâm xôi, Hoa Datura ma mị, Xạ hương trắng, Hoắc hương', 'Ngọt ngào lãng mạn say đắm, lưu hương 8-10 giờ quyến luyến.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (225, 20, 19, 'Nước Hoa Nam Lãng Tử Sâu Lắng Dior Homme Intense Eau De Parfum', 'Hợp chất hoa diên vĩ Tuscan Iris quý tộc kết hợp hạt vông vang và tuyết tùng tạo nên hương thơm mê hoặc.', 'Pháp', 'Hoa diên vĩ Tuscany Iris, Hạt vông vang Ambrette, Tuyết tùng Virginia', 'Mùi hương ấm áp lịch lãm, đẳng cấp số 1 cho những buổi hẹn hò lãng mạn.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (226, 1, 20, 'Xịt Thơm Toàn Thân & Tóc LUNEA Golden Amber Body Mist', 'Xịt thơm body mist dịu ngọt quý phái mang lại sự tự tin và hương thơm lôi cuốn mọi ánh nhìn suốt cả ngày.', 'Việt Nam', 'Tinh dầu hổ phách, Hoa vani Madagascar, Nước cất hoa cam Hậu Giang', 'Lưu hương nhẹ nhàng suốt 4-6 giờ, tạo cảm giác thư giãn sảng khoái và dưỡng ẩm nhẹ cho tóc.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (227, 29, 20, 'Xịt Thơm Toàn Thân Bath & Body Works Into The Night Fine Fragrance Mist', 'Hương thơm dạ tiệc bán chạy nhất của BBW với sự kết hợp ma mị của quả mọng đen, hoa nhài đêm và hổ phách.', 'Mỹ', 'Quả mâm xôi đen, Tinh dầu hoa nhài đêm, Hổ phách đen quý phái', 'Lưu hương 4-6 tiếng trên cơ thể và quần áo, phong cách quyến rũ sang trọng.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (228, 29, 20, 'Xịt Thơm Hoa Anh Đào Bath & Body Works Japanese Cherry Blossom Mist', 'Mùi hương quốc dân huyền thoại sống mãi cùng năm tháng của BBW với hoa anh đào Nhật Bản và quả lê giòn.', 'Mỹ', 'Hoa anh đào Nhật Bản, Quả lê châu Á, Hoa trinh nữ Mimosa, Gỗ đàn hương', 'Dịu dàng thanh lịch, thích hợp dùng hằng ngày đi học đi làm nhẹ nhàng tươi mát.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (229, 29, 20, 'Xịt Thơm Ngọt Ngào Bath & Body Works Warm Vanilla Sugar Fine Fragrance Mist', 'Mùi hương vani đường nâu ấm áp ngọt ngào như mẻ bánh quy bơ vừa mới ra lò.', 'Mỹ', 'Vani Bourbon nguyên chất, Đường nâu caramen, Hoa phong lan trắng', 'Ấm áp ngọt lịm, mang lại cảm giác dễ chịu gần gũi trong những ngày se lạnh.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (230, 30, 20, 'Xịt Thơm Quyến Rũ Victoria''s Secret Pure Seduction Fragrance Mist', 'Mùi hương quả mận chín mọng kết hợp hoa lan Nam Phi nồng nàn mê đắm được triệu cô gái yêu thích.', 'Mỹ', 'Quả mận ép tươi, Hoa lan Nam Phi nghiền, Tinh chất Lô Hội dưỡng da', 'Ngọt ngào trẻ trung năng động, tỏa hương thơm ngát tự tin suốt ngày dài.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (231, 30, 20, 'Xịt Thơm Ấm Áp Victoria''s Secret Bare Vanilla Fragrance Mist', 'Hương vani ấm mịn đánh bông hòa quyện cùng hương táo mềm mại gợi cảm khó cưỡng.', 'Mỹ', 'Vani roi kem béo ngậy, Táo chín ngọt, Tinh chất dưỡng ẩm da', 'Tạo cảm giác ấm áp quyến rũ như một cái ôm êm ái.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (232, 30, 20, 'Xịt Thơm Dịu Ngọt Victoria''s Secret Velvet Petals Fragrance Mist', 'Hương hoa cỏ bồng bềnh hòa quyện hạnh nhân ngào đường đem lại nét đáng yêu dịu dàng.', 'Mỹ', 'Cánh hoa nhung mềm, Hạnh nhân nướng, Chiết xuất hoa cúc La Mã', 'Hương phấn thơm ngọt ngào thư giãn, thích hợp sau khi tắm hoặc trước khi ngủ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (233, 30, 20, 'Xịt Thơm Tươi Mát Đại Dương Victoria''s Secret Aqua Kiss Fragrance Mist', 'Cơn mưa rào mùa hạ tươi mát với hoa lan Nam Phi ướt sương và hoa cúc biển sảng khoái.', 'Mỹ', 'Nước khoáng biển sâu, Hoa lan Nam Phi, Hoa cúc cúc dại', 'Thanh mát sảng khoái đánh bay cái nóng oi bức, tiếp thêm năng lượng ngày mới.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (234, 1, 20, 'Xịt Thơm Tóc & Body Tinh Dầu Hoa Bưởi Cocoon Tươi Mát 140ml', 'Hương hoa bưởi thanh khiết tháng Ba miền Bắc kết hợp nước cất vỏ bưởi giải tỏa căng thẳng.', 'Việt Nam', 'Nước cất hoa bưởi nguyên chất, Tinh dầu hoa cúc, Nước khoáng thiên nhiên', 'Làm thơm dịu mát cơ thể và mái tóc, khử mùi thức ăn bám vào tóc sau khi ăn uống.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (235, 29, 20, 'Xịt Thơm Bữa Tiệc Bãi Biển Bath & Body Works At The Beach Fine Fragrance Mist', 'Hương thơm ngập tràn hơi thở mùa hè với hoa dừa trắng, cam bergamot và làn gió biển ấm áp.', 'Mỹ', 'Nước dừa tươi, Hoa mộc lan dừa, Cam bergamot, Muối biển', 'Đem lại cảm giác thư giãn tựa như đang nằm dài dưới rặng dừa nhiệt đới.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (236, 29, 20, 'Xịt Thơm Ngàn Điều Ước Bath & Body Works A Thousand Wishes Mist', 'Ly rượu sâm panh hồng lấp lánh hòa cùng hoa mẫu đơn pha lê và kem hạnh nhân ngọt ngào.', 'Mỹ', 'Rượu Champagne hồng Procecco, Hoa mẫu đơn pha lê, Hổ phách mạ vàng', 'Không khí lễ hội ngập tràn niềm vui và sự ấm áp lộng lẫy.', 1, 'ACTIVE', '2026-01-01 00:00:00'),
    (237, 30, 20, 'Xịt Thơm Tình Yêu Quyến Rũ Victoria''s Secret Love Spell Fragrance Mist', 'Sự hòa quyện kinh điển giữa hoa anh đào trắng mộng mơ và quả đào mọng nước ngọt ngào.', 'Mỹ', 'Hoa anh đào trắng, Đào tươi ép mật, Chiết xuất cúc La Mã', 'Mùi hương tươi vui ngọt lịm như mối tình đầu e ấp rạng ngời.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (238, 5, 20, 'Xịt Thơm Toàn Thân & Tóc Hương Trà Đen Innisfree Perfumed Body & Hair Mist', 'Hương trà đen thảo mộc thanh tao từ đảo Jeju giúp thanh lọc tâm trí và lưu lại cảm giác dễ chịu.', 'Hàn Quốc', 'Chiết xuất Trà đen đảo Jeju, Tinh dầu hoa cỏ tự nhiên', 'Xịt dưỡng thơm mát nhẹ nhàng cho cả cơ thể và mái tóc khô xơ.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (239, 29, 20, 'Xịt Thơm Thư Giãn Tinh Thần Bath & Body Works Eucalyptus Tea Body Mist', 'Hương thảo mộc tinh tế kết hợp lá khuynh diệp và trà thảo mộc giúp xua tan mệt mỏi sau ngày dài.', 'Mỹ', 'Tinh dầu khuynh diệp nguyên chất, Trà thảo mộc thanh khiết', 'Tạo bầu không khí thư thái bình yên hỗ trợ giấc ngủ ngon sâu.', 0, 'ACTIVE', '2026-01-01 00:00:00'),
    (240, 30, 20, 'Xịt Thơm Bờ Biển Nhiệt Đới Victoria''s Secret Coconut Passion Fragrance Mist', 'Hương thơm kem dừa ấm hòa quyện vani ngọt ngào quyến rũ đưa bạn đến ốc đảo nhiệt đới ngập nắng.', 'Mỹ', 'Cơm dừa nướng, Vani ngọt ấm, Tinh chất hoa cúc Chamomile', 'Lưu hương béo ngọt êm ái, tạo nét thu hút khó cưỡng cho phái đẹp.', 0, 'ACTIVE', '2026-01-01 00:00:00');
