    (1, 1, 1, 1, 1, 5, 'Serum dùng siêu thích luôn, mình dùng hơn 2 tuần thấy nốt mụn khô còi nhanh và bớt bóng dầu hẳn. Hàng chính hãng LUNEA đóng gói rất kỹ!', 'APPROVED', '2026-03-04 10:00:00'),
    (2, 1, 2, 1, 2, 5, 'Niacinamide The Ordinary kiềm dầu tốt, lỗ chân lông 2 bên má nhìn gọn gàng hơn rõ rệt. Rất hài lòng với dịch vụ giao hàng của shop.', 'APPROVED', '2026-03-04 10:15:00'),
    (3, 2, 47, 2, 3, 5, 'Kem chống nắng Anessa chuẩn số 1, thấm nhanh ráo mịn đi đường nắng gắt không bị rát da mặt. 10 điểm cho LUNEA!', 'APPROVED', '2026-03-08 09:30:00');
